export enum Rank {
  IRON = 'Iron',
  BRONZE = 'Bronze',
  SILVER = 'Silver',
  GOLD = 'Gold',
  PLATINUM = 'Platinum',
  DIAMOND = 'Diamond',
  ASCENDANT = 'Ascendant',
  IMMORTAL = 'Immortal',
  RADIANT = 'Radiant'
}

export interface Pricing {
  hours3: number;
  hours12: number;
  hours24: number;
}

export interface Account {
  id: string;
  name: string;
  rank: Rank;
  skins: string[];
  pricing: Pricing;
  imageUrl: string;
  isBooked: boolean;
  bookedUntil: string | null; // ISO Date string
}

export enum BookingStatus {
  PENDING = 'PENDING', // Payment screenshot sent, waiting for admin
  ACTIVE = 'ACTIVE',   // Admin approved, time started
  COMPLETED = 'COMPLETED', // Time over
  CANCELLED = 'CANCELLED'
}

export interface Booking {
  orderId: string;
  accountId: string;
  accountName: string;
  durationLabel: '3 Hours' | '12 Hours' | '24 Hours';
  hours: number;
  totalPrice: number;
  startTime: string; // ISO Date string
  endTime: string;   // ISO Date string
  status: BookingStatus;
  customerName?: string;
  createdAt: string;
}

export const UPI_ID = "krishnavalo@upi"; // Mock UPI ID

import { Account, Booking, Rank, BookingStatus } from '../types';

const ACCOUNTS_KEY = 'kv_accounts';
const BOOKINGS_KEY = 'kv_bookings';

// Seed data
const INITIAL_ACCOUNTS: Account[] = [
  {
    id: 'kv-001',
