import React from 'react';
import { Account } from '../types';
import { Clock, Trophy, Gem, Lock } from 'lucide-react';

interface AccountCardProps {
  account: Account;
  onBook: (account: Account) => void;
}

const AccountCard: React.FC<AccountCardProps> = ({ account, onBook }) => {
  const isAvailable = !account.isBooked;

  const getRankColor = (rank: string) => {
    if (rank.includes('Gold')) return 'text-yellow-400';
    if (rank.includes('Platinum')) return 'text-cyan-400';
    if (rank.includes('Diamond')) return 'text-purple-400';
    if (rank.includes('Ascendant')) return 'text-emerald-400';
    if (rank.includes('Immortal')) return 'text-red-500';
    return 'text-slate-300';
  };

  return (
    <div className={`relative rounded-xl overflow-hidden border transition-all duration-300 hover:scale-[1.02] ${isAvailable ? 'border-white/10 bg-brand-surface hover:shadow-lg hover:shadow-brand-accent/20' : 'border-red-900/30 bg-brand-dark opacity-75'}`}>

      {/* Image Overlay */}
      <div className="relative h-48 w-full overflow-hidden">
        <img 
          src={account.imageUrl} 
          alt={account.name} 
          className="w-full h-full object-cover transition-transform duration-500 hover:scale-110"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-brand-surface to-transparent" />

        {/* Status Badge */}
        <div className="absolute top-3 right-3">
          {isAvailable ? (
            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-500/10 text-green-400 border border-green-500/20 backdrop-blur-md">
              <span className="w-1.5 h-1.5 rounded-full bg-green-400 mr-1.5 animate-pulse" />
              Available
            </span>
          ) : (
            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-500/10 text-red-400 border border-red-500/20 backdrop-blur-md">
              <Lock className="w-3 h-3 mr-1" />
              Booked until {account.bookedUntil ? new Date(account.bookedUntil).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '...'}
            </span>
          )}
        </div>

        {/* Rank Badge */}
        <div className="absolute bottom-3 left-3 flex items-center gap-1.5 bg-black/60 backdrop-blur-md px-2 py-1 rounded-lg border border-white/5">
          <Trophy className={`w-4 h-4 ${getRankColor(account.rank)}`} />
          <span className={`text-sm font-bold tracking-wide ${getRankColor(account.rank)}`}>{account.rank}</span>
        </div>
      </div>

      {/* Content */}
      <div className="p-5">
        <h3 className="text-xl font-display font-bold text-white mb-3 truncate">{account.name}</h3>

        {/* Skins */}
        <div className="mb-4">
          <div className="flex items-center gap-2 text-xs text-slate-400 mb-2 uppercase tracking-wider font-semibold">
            <Gem className="w-3 h-3 text-brand-secondary" />
            Top Skins
          </div>
          <div className="flex flex-wrap gap-2">
            {account.skins.slice(0, 3).map((skin, idx) => (
              <span key={idx} className="text-xs px-2 py-1 rounded bg-white/5 text-slate-300 border border-white/5">
                {skin}
              </span>
            ))}
            {account.skins.length > 3 && (
               <span className="text-xs px-2 py-1 rounded bg-white/5 text-slate-500 border border-white/5">+{account.skins.length - 3}</span>
            )}
          </div>
        </div>

        {/* Pricing Grid */}
        <div className="grid grid-cols-3 gap-2 mb-5">
          <div className="bg-brand-dark p-2 rounded border border-white/5 text-center">
            <div className="text-xs text-slate-500">3 Hours</div>
            <div className="text-sm font-bold text-brand-accent">₹{account.pricing.hours3}</div>
          </div>
          <div className="bg-brand-dark p-2 rounded border border-white/5 text-center">
            <div className="text-xs text-slate-500">12 Hours</div>
            <div className="text-sm font-bold text-brand-accent">₹{account.pricing.hours12}</div>
          </div>
          <div className="bg-brand-dark p-2 rounded border border-white/5 text-center">
            <div className="text-xs text-slate-500">24 Hours</div>
            <div className="text-sm font-bold text-brand-accent">₹{account.pricing.hours24}</div>
          </div>
        </div>

        {/* Action Button */}
        <button
          onClick={() => isAvailable && onBook(account)}
          disabled={!isAvailable}
          className={`w-full py-3 px-4 rounded-lg font-bold uppercase tracking-wider text-sm transition-all duration-200 flex items-center justify-center gap-2
            ${isAvailable 
              ? 'bg-brand-accent hover:bg-red-600 text-white shadow-lg shadow-brand-accent/25' 
              : 'bg-slate-800 text-slate-500 cursor-not-allowed'}`}
        >
          {isAvailable ? (
            <>
              Book Now
            </>
          ) : (
            <>
              Unavailable
            </>
