            </div>

            <div className="flex justify-between items-center pt-4 border-t border-white/10 mb-8">
              <span className="font-bold text-lg">Total</span>
              <span className="font-bold text-2xl text-brand-accent">₹{state.price}</span>
            </div>

            <button 
              onClick={handlePaymentComplete}
              className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-4 rounded-lg flex items-center justify-center gap-2 transition-all shadow-lg shadow-green-600/20"
            >
              <MessageSquare className="w-5 h-5" />
              I Have Paid (Send Screenshot)
            </button>
            <p className="text-xs text-center mt-3 text-slate-500">
              You will be redirected to WhatsApp to verify payment.
            </p>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Checkout;

