              <div className="relative">
                <input 
                  type="text" 
                  value={utr}
                  onChange={(e) => setUtr(e.target.value)}
                  placeholder="e.g. 3245xxxx9812"
                  className="w-full bg-brand-dark border border-white/10 rounded-lg px-4 py-3 pl-10 focus:outline-none focus:border-brand-accent text-white font-mono"
                />
                <CreditCard className="absolute left-3 top-3.5 w-4 h-4 text-slate-500" />
              </div>
              <p className="text-xs text-slate-500 mt-1">Found in your payment app after successful transfer.</p>
            </div>

            <button 
              onClick={handlePaymentComplete}
              disabled={isRedirecting}
              className={`w-full font-bold py-4 rounded-lg flex items-center justify-center gap-2 transition-all shadow-lg 
                ${isRedirecting 
                  ? 'bg-slate-700 text-slate-300 cursor-wait shadow-none' 
                  : 'bg-green-600 hover:bg-green-500 text-white shadow-green-600/20'}`}
            >
              {isRedirecting ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Redirecting to WhatsApp...
                </>
              ) : (
                <>
                  <MessageSquare className="w-5 h-5" />
                  Submit & Get Login
                </>
              )}
            </button>
            <p className="text-xs text-center mt-3 text-slate-500">
              {isRedirecting ? "Please do not close this window." : "Clicking this will open WhatsApp with your order details."}
            </p>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Checkout;

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { StorageService } from '../services/storage';
import { Account, Pricing } from '../types';
import AccountCard from '../components/AccountCard';
import { X, AlertCircle, Calendar, Clock, ArrowRight, ArrowLeft, ChevronRight } from 'lucide-react';

const Browse: React.FC = () => {
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [selectedAccount, setSelectedAccount] = useState<Account | null>(null);

  // Wizard State
  const [step, setStep] = useState<1 | 2>(1);

  // Form Data
  const [selectedDuration, setSelectedDuration] = useState<keyof Pricing | null>(null);
  const [startMode, setStartMode] = useState<'now' | 'later'>('now');
  const [scheduledTime, setScheduledTime] = useState('');

  const navigate = useNavigate();

  // Load accounts and refresh every minute to check availability
  useEffect(() => {
    const load = () => setAccounts(StorageService.getAccounts());
    load();
    const interval = setInterval(load, 60000);
    return () => clearInterval(interval);
  }, []);

  // Reset state when modal opens
  useEffect(() => {
    if (selectedAccount) {
      setStep(1);
      setSelectedDuration('hours3'); // Default choice
      setStartMode('now');
      setScheduledTime('');
    }
  }, [selectedAccount]);

  const handleBookClick = (account: Account) => {
    setSelectedAccount(account);
  };

  const getMinDateTime = () => {
    const now = new Date();
    now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
    return now.toISOString().slice(0, 16);
  };

  const calculateTimes = () => {
    if (!selectedDuration) return { start: null, end: null };

    const hours = selectedDuration === 'hours3' ? 3 : selectedDuration === 'hours12' ? 12 : 24;
    let start = new Date();

    if (startMode === 'later' && scheduledTime) {
      start = new Date(scheduledTime);
    }

    const end = new Date(start.getTime() + hours * 60 * 60 * 1000);
    return { start, end };
  };

  const formatTime12Hour = (date: Date | null) => {
    if (!date) return '--:--';
    return date.toLocaleTimeString('en-IN', { 
      hour: 'numeric', 
      minute: '2-digit', 
      hour12: true 
    });
  };

  const handleNextStep = () => {
    if (selectedDuration) {
      setStep(2);
    }
  };

  const handleProceedToCheckout = () => {
    if (!selectedAccount || !selectedDuration) return;

    if (startMode === 'later' && !scheduledTime) {
      alert("Please select a date and time for your booking.");
      return;
    }

    if (startMode === 'later') {
      const selectedDate = new Date(scheduledTime);
      if (selectedDate < new Date()) {
         alert("Please select a future time.");
         return;
      }
    }

    const hours = selectedDuration === 'hours3' ? 3 : selectedDuration === 'hours12' ? 12 : 24;
    const price = selectedAccount.pricing[selectedDuration];

    navigate('/checkout', { 
      state: { 
        account: selectedAccount,
        hours,
        price,
        durationLabel: selectedDuration === 'hours3' ? '3 Hours' : selectedDuration === 'hours12' ? '12 Hours' : '24 Hours',
        startMode,
        scheduledTime: startMode === 'later' ? scheduledTime : undefined
      } 
    });
  };

  const { start, end } = calculateTimes();

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-3xl font-display font-bold text-white mb-2">Available Accounts</h1>
        <p className="text-slate-400">Choose your weapon. Rent instantly.</p>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {accounts.map(account => (
          <AccountCard 
            key={account.id} 
            account={account} 
            onBook={handleBookClick} 
          />
        ))}
      </div>

      {/* Empty State */}
      {accounts.length === 0 && (
        <div className="text-center py-20 text-slate-500">
          No accounts found. Please check back later.
        </div>
      )}

      {/* Booking Modal */}
      {selectedAccount && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-brand-surface border border-white/10 rounded-2xl w-full max-w-md overflow-hidden shadow-2xl animate-in fade-in zoom-in duration-200 flex flex-col max-h-[90vh]">

            {/* Header */}
            <div className="p-4 border-b border-white/10 flex justify-between items-center bg-brand-dark/50 shrink-0">
              <div className="flex items-center gap-2">
                {step === 2 && (
                  <button 
                    onClick={() => setStep(1)}
                    className="mr-1 p-1 hover:bg-white/10 rounded-full transition-colors"
                  >
                    <ArrowLeft className="w-5 h-5 text-slate-300" />
                  </button>
                )}
                <h3 className="font-bold text-lg">
                  {step === 1 ? 'Select Duration' : 'Select Time'}
                </h3>
              </div>
              <button 
                onClick={() => setSelectedAccount(null)}
                className="text-slate-400 hover:text-white transition-colors"
              >
                <X className="w-6 h-6" />
              </button>
            </div>

            {/* Step 1: Duration Selection */}
            {step === 1 && (
              <div className="p-6 overflow-y-auto custom-scrollbar animate-in slide-in-from-left-4 duration-300">

                {/* Account Preview */}
                <div className="flex items-center gap-4 mb-6">
                  <img src={selectedAccount.imageUrl} alt="" className="w-16 h-16 rounded object-cover border border-white/10" />
                  <div>
                    <h4 className="font-bold text-white text-lg">{selectedAccount.name}</h4>
                    <p className="text-sm text-brand-accent font-medium">{selectedAccount.rank}</p>
                  </div>
                </div>

                <div className="space-y-3 mb-8">
                  {[
                    { id: 'hours3', label: '3 Hours', price: selectedAccount.pricing.hours3 },
                    { id: 'hours12', label: '12 Hours', price: selectedAccount.pricing.hours12 },
                    { id: 'hours24', label: '24 Hours', price: selectedAccount.pricing.hours24 },
                  ].map((option) => (
                    <label 
                      key={option.id}
                      className={`flex items-center justify-between p-4 rounded-xl border cursor-pointer transition-all ${
                        selectedDuration === option.id 
                          ? 'border-brand-accent bg-brand-accent/10 ring-1 ring-brand-accent shadow-[0_0_15px_rgba(255,70,85,0.1)]' 
                          : 'border-white/10 bg-brand-dark hover:border-white/30 hover:bg-white/5'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${
                          selectedDuration === option.id ? 'border-brand-accent' : 'border-slate-500'
                        }`}>
                          {selectedDuration === option.id && <div className="w-2.5 h-2.5 rounded-full bg-brand-accent" />}
                        </div>
                        <span className="font-medium text-white text-lg">{option.label}</span>
                      </div>
                      <span className="font-bold text-xl text-brand-accent">₹{option.price}</span>
                    </label>
                  ))}
                </div>

                <button 
                  onClick={handleNextStep}
                  className="w-full bg-brand-accent hover:bg-red-600 text-white font-bold py-4 rounded-lg transition-all shadow-lg shadow-brand-accent/20 flex items-center justify-center gap-2 group"
                >
                  Select Time & Date
                  <ChevronRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                </button>
              </div>
            )}

            {/* Step 2: Time Selection */}
            {step === 2 && (
              <div className="p-6 overflow-y-auto custom-scrollbar animate-in slide-in-from-right-4 duration-300">

                {/* Summary of Step 1 */}
                <div className="bg-brand-dark border border-white/10 rounded-lg p-3 flex justify-between items-center mb-6">
                  <div>
                    <span className="text-xs text-slate-500 uppercase tracking-wide">Selected Plan</span>
                    <div className="font-bold text-white">
                      {selectedDuration === 'hours3' ? '3 Hours' : selectedDuration === 'hours12' ? '12 Hours' : '24 Hours'}
                    </div>
                  </div>
                  <div className="font-bold text-brand-accent text-xl">
                    ₹{selectedDuration && selectedAccount.pricing[selectedDuration as keyof Pricing]}
                  </div>
                </div>

                <div className="mb-6">
                  <label className="text-sm text-slate-400 font-medium mb-3 block">When would you like to play?</label>

                  <div className="grid grid-cols-2 gap-3 mb-6">
                    <button
                      onClick={() => setStartMode('now')}
                      className={`py-3 px-2 text-sm font-bold rounded-xl border transition-all flex flex-col items-center gap-2 ${
                        startMode === 'now' 
                          ? 'bg-brand-accent text-white border-brand-accent shadow-lg shadow-brand-accent/20' 
                          : 'bg-brand-dark text-slate-400 border-white/10 hover:border-white/30'
                      }`}
                    >
                      <Clock className="w-5 h-5" />
                      Start Now
                    </button>
                    <button
                      onClick={() => setStartMode('later')}
                      className={`py-3 px-2 text-sm font-bold rounded-xl border transition-all flex flex-col items-center gap-2 ${
                        startMode === 'later' 
                          ? 'bg-brand-accent text-white border-brand-accent shadow-lg shadow-brand-accent/20' 
                          : 'bg-brand-dark text-slate-400 border-white/10 hover:border-white/30'
                      }`}
                    >
                      <Calendar className="w-5 h-5" />
                      Schedule
                    </button>
                  </div>

                  {startMode === 'later' && (
                    <div className="animate-in slide-in-from-top-2 duration-200 mb-6">
                      <label className="text-xs text-slate-500 mb-1.5 block">Select Date & Time</label>
                      <div className="relative">
                        <input 
                          type="datetime-local" 
                          min={getMinDateTime()}
                          value={scheduledTime}
                          onChange={(e) => setScheduledTime(e.target.value)}
                          className="w-full bg-brand-dark border border-white/10 rounded-lg px-4 py-3 text-white focus:border-brand-accent focus:outline-none [color-scheme:dark]"
                        />
                        <Calendar className="absolute right-4 top-3.5 w-5 h-5 text-slate-400 pointer-events-none" />
                      </div>
                    </div>
                  )}

                  {/* Time Slot Preview Card */}
                  <div className="bg-gradient-to-br from-brand-dark to-brand-surface border border-white/10 rounded-xl p-4 relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-2 opacity-10">
                      <Clock className="w-24 h-24" />
                    </div>
                    <div className="relative z-10">
                      <h5 className="text-slate-400 text-xs uppercase tracking-widest font-bold mb-3">Your Time Slot</h5>
                      <div className="flex items-center justify-between gap-2">
                        <div className="text-center">
                          <div className="text-2xl font-display font-bold text-white leading-none mb-1">
                            {startMode === 'now' ? 'Now' : formatTime12Hour(start)}
                          </div>
                          <div className="text-[10px] text-slate-500 uppercase font-bold">Start</div>
                        </div>

                        <div className="flex-1 h-0.5 bg-white/10 relative">
                           <div className="absolute right-0 -top-1.5">
                              <ArrowRight className="w-4 h-4 text-brand-accent" />
                           </div>
                        </div>

                        <div className="text-center">
                          <div className="text-2xl font-display font-bold text-brand-accent leading-none mb-1">
                            {formatTime12Hour(end)}
                          </div>
                          <div className="text-[10px] text-slate-500 uppercase font-bold">End</div>
                        </div>
                      </div>

                      {startMode === 'later' && start && (
                        <div className="mt-3 text-center text-xs text-slate-400 border-t border-white/5 pt-2">
                           Date: <span className="text-white">{start.toLocaleDateString('en-IN', { weekday: 'short', month: 'short', day: 'numeric'})}</span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>

                {/* Warning */}
                <div className="bg-yellow-500/10 border border-yellow-500/20 p-3 rounded-lg flex gap-3 items-start mb-6">
                  <AlertCircle className="w-4 h-4 text-yellow-500 shrink-0 mt-0.5" />
                  <p className="text-xs text-yellow-200/80 leading-relaxed">
                    By proceeding, you agree to our Terms. Rank pushing is strictly prohibited.
                  </p>
                </div>

                <div className="flex gap-3">
                  <button 
                     onClick={() => setStep(1)}
                     className="px-4 py-3 rounded-lg border border-white/10 text-slate-300 font-bold hover:bg-white/5 transition-colors"
                  >
                    Back
                  </button>
                  <button 
                    onClick={handleProceedToCheckout}
                    className="flex-1 bg-brand-accent hover:bg-red-600 text-white font-bold py-3 rounded-lg transition-colors shadow-lg shadow-brand-accent/20"
                  >
                    Proceed to Payment
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default Browse;

import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate, Navigate } from 'react-router-dom';
import { Account, UPI_ID, BookingStatus, Booking } from '../types';
import { StorageService } from '../services/storage';
import { CheckCircle, Copy, ArrowRight, MessageSquare, Timer, Loader2, CreditCard, CalendarClock, Smartphone, ShieldCheck } from 'lucide-react';

interface CheckoutState {
  account: Account;
  hours: number;
  price: number;
  durationLabel: '3 Hours' | '12 Hours' | '24 Hours';
  startMode: 'now' | 'later';
  scheduledTime?: string;
}

const Checkout: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const state = location.state as CheckoutState;

  const [orderId, setOrderId] = useState('');
  const [timer, setTimer] = useState(600); // 10 minutes for payment
  const [isVerifying, setIsVerifying] = useState(false);
  const [verificationStep, setVerificationStep] = useState<'idle' | 'checking' | 'confirmed'>('idle');

  useEffect(() => {
    if (state) {
      // Generate unique order ID once
      const id = 'KV-' + Math.floor(1000 + Math.random() * 9000);
      setOrderId(id);
    }
  }, [state]);

  // Payment Timer countdown
  useEffect(() => {
    if (timer > 0) {
      const interval = setInterval(() => setTimer(t => t - 1), 1000);
      return () => clearInterval(interval);
    }
  }, [timer]);

  if (!state) {
    return <Navigate to="/browse" />;
  }

  // Calculate rental period for display
  const startDateTime = state.startMode === 'later' && state.scheduledTime 
    ? new Date(state.scheduledTime) 
    : new Date();

  const endDateTime = new Date(startDateTime.getTime() + state.hours * 60 * 60 * 1000);

  const formatTimer = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  // Construct UPI URI with amount and order ID
  // tn (Transaction Note) is critical here - it puts the Order ID in the bank statement for the admin
  const upiString = `upi://pay?pa=${UPI_ID}&pn=KrishnaValo&am=${state.price.toFixed(2)}&cu=INR&tn=${orderId}`;
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=250x250&margin=10&data=${encodeURIComponent(upiString)}`;

  const handlePayViaApp = () => {
    window.location.href = upiString;
  };

  const handleVerifyAndProceed = async () => {
    if (isVerifying) return;

    setIsVerifying(true);
    setVerificationStep('checking');

    // Simulate verification delay for better UX (Automated feel)
    await new Promise(resolve => setTimeout(resolve, 2000));

    setVerificationStep('confirmed');
    await new Promise(resolve => setTimeout(resolve, 800));

    // 1. Create Booking Record locally
    const newBooking: Booking = {
      orderId,
      accountId: state.account.id,
      accountName: state.account.name,
      durationLabel: state.durationLabel,
      hours: state.hours,
      totalPrice: state.price,
      startTime: startDateTime.toISOString(),
      endTime: endDateTime.toISOString(),
      status: BookingStatus.PENDING,
      createdAt: new Date().toISOString()
    };

    StorageService.createBooking(newBooking);

    // 2. Construct WhatsApp Message (Without UTR, relying on Order ID)
    const timeString = state.startMode === 'later' 
      ? startDateTime.toLocaleString('en-IN', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
      : "Immediate";

    const message = `
*PAYMENT COMPLETED*
---------------------
*Order ID:* ${orderId}
*Valorant ID:* ${state.account.name}
*Duration:* ${state.durationLabel}
*Price:* ₹${state.price}
*Start Time:* ${timeString}
---------------------
I have paid via UPI. Please verify Order ID and send login details.
    `.trim();

    // 3. Redirect to WhatsApp
    const whatsappUrl = `https://wa.me/918530085116?text=${encodeURIComponent(message)}`;
    window.location.href = whatsappUrl;
  };

  return (
    <div className="max-w-3xl mx-auto px-4 py-8">
      <div className="flex items-center gap-2 mb-6 text-slate-400 text-sm">
        <span onClick={() => navigate('/browse')} className="cursor-pointer hover:text-white">Browse</span>
        <ArrowRight className="w-3 h-3" />
        <span className="text-white">Checkout</span>
      </div>

      <div className="grid md:grid-cols-2 gap-8">

        {/* Left Column: Payment Details */}
        <div className="space-y-6">
          <div className="bg-brand-surface border border-white/10 rounded-xl p-6 relative overflow-hidden">
            {/* Background Glow */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-brand-accent/10 blur-3xl rounded-full pointer-events-none"></div>

            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
              <span className="w-8 h-8 rounded-full bg-brand-accent flex items-center justify-center text-sm">1</span>
              Make Payment
            </h2>

            {/* Mobile: Pay Button */}
            <div className="md:hidden mb-6">
              <button 
                onClick={handlePayViaApp}
                className="w-full bg-white text-brand-darker font-bold py-4 rounded-xl shadow-lg flex items-center justify-center gap-2 hover:bg-slate-100 transition-colors animate-pulse"
              >
                <Smartphone className="w-6 h-6" />
                Tap to Pay via UPI App
              </button>
              <p className="text-center text-xs text-slate-400 mt-2">Opens GPay, PhonePe, Paytm, etc.</p>
            </div>

            {/* Desktop/QR Display */}
            <div className="flex flex-col items-center justify-center p-6 bg-white rounded-lg mb-4 shadow-inner relative group">
              <img 
                src={qrCodeUrl} 
                alt="UPI QR Code" 
                className="w-48 h-48 mb-2 mix-blend-multiply"
              />
              <p className="text-brand-dark font-bold text-lg">₹{state.price}</p>

              {/* Scan Overlay for visual flair */}
              <div className="absolute inset-0 bg-brand-accent/5 pointer-events-none" />
              <div className="absolute top-0 left-0 w-full h-1 bg-brand-accent/50 animate-[scan_2s_infinite_linear] pointer-events-none" />
            </div>

            <div className="flex items-center justify-between bg-brand-dark p-3 rounded border border-white/10">
              <span className="text-sm text-slate-400">UPI ID:</span>
              <div className="flex items-center gap-2">
                <span className="font-mono text-sm">{UPI_ID}</span>
                <button 
                   onClick={() => navigator.clipboard.writeText(UPI_ID)}
                   className="text-brand-accent hover:text-white"
                >
                  <Copy className="w-4 h-4" />
                </button>
              </div>
            </div>

            <div className="mt-4 p-3 bg-green-500/10 border border-green-500/20 rounded text-sm text-green-300 flex items-start gap-2">
               <ShieldCheck className="w-5 h-5 shrink-0" />
               <p>
                 <strong>Order ID {orderId}</strong> is auto-linked. You do <u>not</u> need to enter UTR manually.
               </p>
            </div>
          </div>
        </div>

        {/* Right Column: Order Summary */}
        <div className="space-y-6">
           {/* Timer */}
           <div className="bg-brand-surface border border-brand-accent/30 rounded-xl p-4 flex items-center justify-between shadow-[0_0_15px_rgba(255,70,85,0.1)]">
             <div className="flex items-center gap-2 text-brand-accent">
               <Timer className="w-5 h-5" />
               <span className="font-bold">Payment Session</span>
             </div>
             <div className="font-mono text-xl font-bold">{formatTimer(timer)}</div>
           </div>

          <div className="bg-brand-surface border border-white/10 rounded-xl p-6">
            <h2 className="text-xl font-bold mb-4">Order Summary</h2>

            <div className="flex gap-4 mb-6 pb-6 border-b border-white/10">
              <img src={state.account.imageUrl} className="w-20 h-20 rounded object-cover" alt="" />
              <div>
                <h3 className="font-bold text-lg">{state.account.name}</h3>
                <span className="text-sm text-brand-secondary bg-brand-secondary/10 px-2 py-0.5 rounded border border-brand-secondary/20">
                  {state.account.rank}
                </span>
              </div>
            </div>

            <div className="space-y-3 mb-6">
              <div className="flex justify-between text-slate-300">
                <span>Order ID</span>
                <span className="font-mono text-white">{orderId}</span>
              </div>
              <div className="flex justify-between text-slate-300">
                <span>Duration</span>
                <span className="text-white">{state.durationLabel}</span>
              </div>

              {/* Scheduled Time Display */}
              <div className="bg-white/5 rounded-lg p-3 border border-white/5 mt-2">
                <div className="flex items-start gap-2 mb-2">
                  <CalendarClock className="w-4 h-4 text-brand-accent mt-0.5" />
                  <span className="text-sm font-bold text-white">Rental Schedule</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-slate-400">Start:</span>
                  <span className="text-white font-mono">
                    {state.startMode === 'now' 
                      ? 'Immediate' 
                      : startDateTime.toLocaleString([], {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'})}
                  </span>
                </div>
                <div className="flex justify-between text-sm mt-1">
                   <span className="text-slate-400">End:</span>
                   <span className="text-white font-mono">
                     {endDateTime.toLocaleString([], {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'})}
                   </span>
                </div>
              </div>

              <div className="flex justify-between text-slate-300 pt-2">
                <span>Subtotal</span>
                <span className="text-white">₹{state.price}</span>
              </div>
            </div>

            <div className="flex justify-between items-center pt-4 border-t border-white/10 mb-6">
              <span className="font-bold text-lg">Total</span>
              <span className="font-bold text-2xl text-brand-accent">₹{state.price}</span>
            </div>

            {/* Simulated Automated Verification Button */}
            <button 
              onClick={handleVerifyAndProceed}
              disabled={isVerifying}
              className={`w-full font-bold py-4 rounded-lg flex items-center justify-center gap-2 transition-all shadow-lg overflow-hidden relative
                ${verificationStep === 'confirmed'
                  ? 'bg-green-600 text-white'
                  : 'bg-brand-accent hover:bg-red-600 text-white shadow-brand-accent/20'}`}
            >
              {verificationStep === 'idle' && (
                <>
                  <CheckCircle className="w-5 h-5" />
                  I Have Paid - Verify Now
                </>
              )}

              {verificationStep === 'checking' && (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Verifying Payment...
                </>
              )}

              {verificationStep === 'confirmed' && (
                <>
                  <CheckCircle className="w-5 h-5" />
                  Verified! Redirecting...
                </>
              )}
            </button>
            <p className="text-xs text-center mt-3 text-slate-500">
               Automated check. Please ensure payment is successful before clicking.
            </p>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Checkout;

