                  {skin}
                </span>

                {/* Custom Tooltip */}
                <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 mb-2 px-3 py-1.5 bg-brand-darker border border-brand-accent/30 rounded-lg text-xs font-medium text-white opacity-0 group-hover:opacity-100 transition-all duration-200 pointer-events-none whitespace-nowrap z-20 shadow-[0_0_15px_rgba(0,0,0,0.5)]">
                  {skin}
                  {/* Arrow */}
                  <div className="absolute top-full left-1/2 transform -translate-x-1/2 -mt-1 border-4 border-transparent border-t-brand-accent/30"></div>
                </div>
              </div>
