            {account.skins.length > 3 && (
               <div className="group relative">
                 <span className="cursor-help text-xs px-2 py-1 rounded bg-white/5 text-slate-500 border border-white/5 hover:border-white/20 transition-colors block">
                   +{account.skins.length - 3}
