            <div className="absolute top-0 right-0 bg-brand-accent text-white text-[9px] px-1 rounded-bl shadow-sm">
              -10%
            </div>
            <div className="text-xs text-slate-500 mt-1">24 Hours</div>
            <div className="text-sm font-bold text-brand-accent leading-tight">
               <span className="line-through text-[10px] text-slate-500 mr-1 opacity-70">₹{account.pricing.hours24}</span>
               ₹{Math.floor(account.pricing.hours24 * 0.9)}
            </div>
          </div>
        </div>

        {/* Action Button */}
        <button
          onClick={() => isAvailable && onBook(account)}
          disabled={!isAvailable}
          className={`w-full py-3 px-4 rounded-lg font-bold uppercase tracking-wider text-sm transition-all duration-200 flex items-center justify-center gap-2
            ${isAvailable 
              ? 'bg-brand-accent hover:bg-red-600 text-white shadow-lg shadow-brand-accent/25' 
              : 'bg-slate-800 text-slate-500 cursor-not-allowed'}`}
        >
          {isAvailable ? (
            <>
              Book Now
            </>
          ) : (
            <>
              Unavailable
            </>
          )}
        </button>
      </div>
    </div>
  );
};

