                  />
                  <button onClick={addSkin} type="button" className="bg-brand-accent px-4 rounded text-white font-bold">+</button>
                </div>
                <div className="flex flex-wrap gap-2 mt-2">
                   {newAccount.skins?.map((s, i) => (
                      <span key={i} className="bg-white/10 px-2 py-1 rounded text-xs">{s}</span>
                   ))}
                </div>
              </div>
            </div>

            <div className="flex gap-4 mt-6">
              <button 
                onClick={handleAddAccount} 
                disabled={isSubmitting}
                className={`flex-1 bg-brand-accent hover:bg-red-600 py-3 rounded font-bold text-white flex items-center justify-center gap-2 transition-all ${isSubmitting ? 'opacity-75 cursor-not-allowed' : ''}`}
