              <div 
                key={account.id} 
                className={`relative group transition-all duration-200 ${selectedIds.has(account.id) ? 'ring-2 ring-brand-accent transform scale-[1.02] z-10' : ''}`}
                onClick={(e) => {
                  // Allow selecting by clicking anywhere on the card
                  handleToggleSelect(account.id);
                }}
              >
                {/* Reusing card structure broadly, but simplified for admin */}
                <div className="bg-brand-surface border border-white/10 rounded-xl overflow-hidden h-full cursor-pointer">
                  <div className="h-40 bg-gray-800 relative">
                     <img src={account.imageUrl} className="w-full h-full object-cover opacity-50" alt={account.name} />
                     <div className="absolute inset-0 flex items-center justify-center">
                        <span className="font-bold text-xl px-2 text-center drop-shadow-md">{account.name}</span>
                     </div>

                     {/* Selection Checkbox Overlay */}
                     <div className="absolute top-3 left-3 z-40">
                       <button 
                         onClick={(e) => handleToggleSelect(account.id, e)}
                         className={`w-6 h-6 rounded border flex items-center justify-center transition-all ${selectedIds.has(account.id) ? 'bg-brand-accent border-brand-accent text-white' : 'bg-black/50 border-white/30 text-transparent hover:border-white'}`}
                       >
                         <Check className="w-4 h-4" />
                       </button>
                     </div>
                  </div>
                  <div className="p-4 text-sm space-y-2 bg-brand-surface">
                    <div className="flex justify-between border-b border-white/5 pb-2">
                      <span className="text-slate-400">ID:</span>
                      <span className="font-mono text-xs text-slate-500">{account.id}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-400">Status:</span>
                      <span className={`font-bold ${account.isBooked ? 'text-red-400' : 'text-green-400'}`}>{account.isBooked ? 'Booked' : 'Available'}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-400">Rank:</span>
                      <span>{account.rank}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-400">Skins:</span>
                      <span>{account.totalSkins || account.skins.length}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-400">Price (3h):</span>
                      <span>₹{account.pricing.hours3}</span>
                    </div>
                  </div>
                </div>

                {/* Delete Button - Fixed: Always visible, higher z-index, explicit background */}
                <div className="absolute top-3 right-3 z-50">
                  <button 
                    onClick={(e) => handleDeleteAccount(account.id, e)} 
                    className="p-2 bg-black/60 backdrop-blur-md border border-red-500/50 text-red-500 rounded-lg hover:bg-red-600 hover:text-white transition-all shadow-lg hover:shadow-red-500/20 cursor-pointer flex items-center justify-center pointer-events-auto"
                    title="Delete Account"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </>
      )}

      {/* Add Account Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-brand-surface border border-white/10 rounded-2xl w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto animate-in fade-in zoom-in-95 duration-200">
            <h2 className="text-xl font-bold mb-4">Add New Account</h2>

            <div className="space-y-4">
              <div>
                <label className="block text-sm text-slate-400 mb-1">Account Name</label>
                <input 
                  className="w-full bg-brand-dark border border-white/10 rounded p-2 text-white" 
                  value={newAccount.name} 
                  onChange={e => setNewAccount({...newAccount, name: e.target.value})} 
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                   <label className="block text-sm text-slate-400 mb-1">Rank</label>
                   <select 
                      className="w-full bg-brand-dark border border-white/10 rounded p-2 text-white"
                      value={newAccount.rank}
                      onChange={e => setNewAccount({...newAccount, rank: e.target.value as Rank})}
                   >
                     {Object.values(Rank).map(r => <option key={r} value={r}>{r}</option>)}
                   </select>
                </div>
                <div>
                  <label className="block text-sm text-slate-400 mb-1">Image URL</label>
                  <input 
                    className="w-full bg-brand-dark border border-white/10 rounded p-2 text-white" 
                    value={newAccount.imageUrl} 
                    onChange={e => setNewAccount({...newAccount, imageUrl: e.target.value})} 
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm text-slate-400 mb-1">Pricing (3h / 12h / 24h)</label>
                <div className="grid grid-cols-3 gap-2">
                   <input type="number" placeholder="3h" className="bg-brand-dark border border-white/10 rounded p-2 text-white" 
                      onChange={e => setNewAccount({...newAccount, pricing: {...newAccount.pricing!, hours3: parseInt(e.target.value)}})} />
                   <input type="number" placeholder="12h" className="bg-brand-dark border border-white/10 rounded p-2 text-white" 
                      onChange={e => setNewAccount({...newAccount, pricing: {...newAccount.pricing!, hours12: parseInt(e.target.value)}})} />
                   <input type="number" placeholder="24h" className="bg-brand-dark border border-white/10 rounded p-2 text-white" 
                      onChange={e => setNewAccount({...newAccount, pricing: {...newAccount.pricing!, hours24: parseInt(e.target.value)}})} />
                </div>
              </div>

              <div>
                <label className="block text-sm text-slate-400 mb-1">Total Skin Count (Optional)</label>
                <input 
                  type="number" 
                  className="w-full bg-brand-dark border border-white/10 rounded p-2 text-white" 
                  value={newAccount.totalSkins || ''} 
                  onChange={e => setNewAccount({...newAccount, totalSkins: e.target.value ? parseInt(e.target.value) : undefined})}
                  placeholder="e.g. 150 (Leave empty to use list count)"
                />
              </div>

              <div>
                <label className="block text-sm text-slate-400 mb-1">Highlighted Skins</label>
                <div className="flex gap-2">
                  <input 
                    className="flex-1 bg-brand-dark border border-white/10 rounded p-2 text-white" 
                    value={skinInput}
                    onChange={e => setSkinInput(e.target.value)}
                    placeholder="Enter skin name"
                  />
                  <button onClick={addSkin} type="button" className="bg-brand-accent px-4 rounded text-white font-bold">+</button>
                </div>
                <div className="flex flex-wrap gap-2 mt-2">
                   {newAccount.skins?.map((s, i) => (
                      <span key={i} className="bg-white/10 px-2 py-1 rounded text-xs">{s}</span>
                   ))}
                </div>
              </div>
            </div>

            <div className="flex gap-4 mt-6">
              <button 
                onClick={handleAddAccount} 
                disabled={isSubmitting}
                className={`flex-1 bg-brand-accent hover:bg-red-600 py-3 rounded font-bold text-white flex items-center justify-center gap-2 transition-all ${isSubmitting ? 'opacity-75 cursor-not-allowed' : ''}`}
              >
                {isSubmitting ? (
                  <>
                    <Loader2 className="w-5 h-5 animate-spin" />
                    Adding...
                  </>
                ) : (
                  'Add Account'
                )}
              </button>
              <button 
                onClick={() => !isSubmitting && setShowAddModal(false)} 
                disabled={isSubmitting}
                className={`flex-1 bg-transparent border border-white/20 hover:bg-white/5 py-3 rounded font-bold text-white transition-colors ${isSubmitting ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Navigate, useNavigate } from 'react-router-dom';
import { StorageService } from '../services/storage';
import { Account, Booking, BookingStatus, Rank } from '../types';
import { Plus, Trash2, Check, X, Eye, Edit2, Loader2, LogOut, Square, CheckSquare, BarChart3, IndianRupee, Users, Gamepad2, TrendingUp } from 'lucide-react';

const AdminDashboard: React.FC = () => {
  const navigate = useNavigate();
  // Check both localStorage (Remember Me) and sessionStorage (One time login)
  const isAuthenticated = localStorage.getItem('isAdmin') === 'true' || sessionStorage.getItem('isAdmin') === 'true';

  const [activeTab, setActiveTab] = useState<'bookings' | 'accounts'>('bookings');
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // New Account Form State
  const [showAddModal, setShowAddModal] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newAccount, setNewAccount] = useState<Partial<Account>>({
    name: '',
    rank: Rank.IRON,
    skins: [],
    totalSkins: undefined,
    pricing: { hours3: 0, hours12: 0, hours24: 0 },
    imageUrl: 'https://picsum.photos/400/300'
  });
  const [skinInput, setSkinInput] = useState('');

  const refreshData = () => {
    setBookings(StorageService.getBookings());
    setAccounts(StorageService.getAccounts());
    setSelectedIds(new Set()); // Reset selection on refresh
  };

  useEffect(() => {
    if (isAuthenticated) refreshData();
  }, [isAuthenticated]);

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    // 1. Total Bookings (All Time)
    const totalBookings = bookings.length;

    // 2. Monthly Revenue (Active + Completed bookings created this month)
    const monthlyRevenue = bookings
      .filter(b => {
        const bookingDate = new Date(b.createdAt);
        return (
          bookingDate.getMonth() === currentMonth && 
          bookingDate.getFullYear() === currentYear &&
          (b.status === BookingStatus.ACTIVE || b.status === BookingStatus.COMPLETED)
        );
      })
      .reduce((sum, b) => sum + b.totalPrice, 0);

    // 3. Active Rentals (Currently Booked Accounts)
    const activeRentals = accounts.filter(a => a.isBooked).length;

    // 4. Total Inventory
    const totalInventory = accounts.length;

    return { totalBookings, monthlyRevenue, activeRentals, totalInventory };
  }, [bookings, accounts]);

  if (!isAuthenticated) return <Navigate to="/admin" />;

  // --- Handlers ---

  const handleLogout = () => {
    localStorage.removeItem('isAdmin');
    sessionStorage.removeItem('isAdmin');
    navigate('/admin');
  };

  const handleStatusUpdate = (orderId: string, status: BookingStatus) => {
    StorageService.updateBookingStatus(orderId, status);
    refreshData();
  };

  const handleDeleteAccount = (id: string, e: React.MouseEvent) => {
    // Stop propagation to prevent any parent click events
    e.stopPropagation();
    e.preventDefault();

    if (window.confirm('Are you sure you want to delete this account? This action cannot be undone.')) {
      const updatedAccounts = StorageService.deleteAccount(id);
      setAccounts(updatedAccounts); // Update state directly

      // Remove from selection if it was selected
      if (selectedIds.has(id)) {
        const newSet = new Set(selectedIds);
        newSet.delete(id);
        setSelectedIds(newSet);
      }
    }
  };

  const handleToggleSelect = (id: string, e?: React.MouseEvent) => {
    if (e) {
      e.stopPropagation();
      e.preventDefault();
    }
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedIds(newSet);
  };

  const handleSelectAll = () => {
    if (selectedIds.size === accounts.length && accounts.length > 0) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(accounts.map(a => a.id)));
    }
  };

  const handleBulkDelete = () => {
    if (selectedIds.size === 0) return;

    if (window.confirm(`Are you sure you want to delete ${selectedIds.size} selected accounts? This cannot be undone.`)) {
       const updatedAccounts = StorageService.deleteAccounts(Array.from(selectedIds));
       setAccounts(updatedAccounts);
       setSelectedIds(new Set());
    }
  };

  const handleAddAccount = () => {
    if (!newAccount.name || !newAccount.pricing) return;

    setIsSubmitting(true);

    // Simulate network delay
    setTimeout(() => {
      const account: Account = {
        id: 'kv-' + Date.now(),
        name: newAccount.name,
        rank: newAccount.rank as Rank,
        skins: newAccount.skins || [],
        totalSkins: newAccount.totalSkins,
        pricing: newAccount.pricing as any,
        imageUrl: newAccount.imageUrl || '',
        isBooked: false,
        bookedUntil: null
      };

      StorageService.saveAccount(account);

      // Reset form
      setNewAccount({
        name: '',
        rank: Rank.IRON,
        skins: [],
        totalSkins: undefined,
        pricing: { hours3: 0, hours12: 0, hours24: 0 },
        imageUrl: 'https://picsum.photos/400/300'
      });
      setSkinInput('');

      refreshData();
      setIsSubmitting(false);
      setShowAddModal(false);
    }, 1500);
  };

  const addSkin = () => {
    if(skinInput) {
      setNewAccount({...newAccount, skins: [...(newAccount.skins || []), skinInput]});
      setSkinInput('');
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
        <h1 className="text-3xl font-display font-bold">Admin Dashboard</h1>

        <div className="flex items-center gap-4">
          <button 
            onClick={handleLogout}
            className="p-2.5 bg-brand-surface border border-white/10 rounded-lg text-slate-400 hover:text-white hover:border-red-500 hover:bg-red-500/10 transition-all"
            title="Logout"
          >
            <LogOut className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
        <div className="bg-brand-surface border border-white/10 rounded-xl p-5 flex items-center justify-between shadow-lg shadow-black/20">
           <div>
             <p className="text-slate-400 text-xs uppercase tracking-widest font-bold mb-1">Total Revenue (Month)</p>
             <h3 className="text-2xl font-bold text-green-400 flex items-center">
               <IndianRupee className="w-5 h-5 mr-1" />{stats.monthlyRevenue}
             </h3>
           </div>
           <div className="w-10 h-10 rounded-full bg-green-500/10 flex items-center justify-center border border-green-500/20">
             <TrendingUp className="w-5 h-5 text-green-400" />
           </div>
        </div>

        <div className="bg-brand-surface border border-white/10 rounded-xl p-5 flex items-center justify-between shadow-lg shadow-black/20">
           <div>
             <p className="text-slate-400 text-xs uppercase tracking-widest font-bold mb-1">Total Bookings</p>
             <h3 className="text-2xl font-bold text-white">{stats.totalBookings}</h3>
           </div>
           <div className="w-10 h-10 rounded-full bg-blue-500/10 flex items-center justify-center border border-blue-500/20">
             <BarChart3 className="w-5 h-5 text-blue-400" />
           </div>
        </div>

        <div className="bg-brand-surface border border-white/10 rounded-xl p-5 flex items-center justify-between shadow-lg shadow-black/20">
           <div>
             <p className="text-slate-400 text-xs uppercase tracking-widest font-bold mb-1">Active Rentals</p>
             <h3 className="text-2xl font-bold text-brand-accent">{stats.activeRentals}</h3>
           </div>
           <div className="w-10 h-10 rounded-full bg-brand-accent/10 flex items-center justify-center border border-brand-accent/20">
             <Gamepad2 className="w-5 h-5 text-brand-accent" />
           </div>
        </div>

        <div className="bg-brand-surface border border-white/10 rounded-xl p-5 flex items-center justify-between shadow-lg shadow-black/20">
           <div>
             <p className="text-slate-400 text-xs uppercase tracking-widest font-bold mb-1">Total Inventory</p>
             <h3 className="text-2xl font-bold text-purple-400">{stats.totalInventory}</h3>
           </div>
           <div className="w-10 h-10 rounded-full bg-purple-500/10 flex items-center justify-center border border-purple-500/20">
             <Users className="w-5 h-5 text-purple-400" />
           </div>
        </div>
      </div>

      <div className="flex bg-brand-dark p-1 rounded-lg border border-white/10 w-fit mb-6">
        <button 
          onClick={() => setActiveTab('bookings')}
          className={`px-6 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'bookings' ? 'bg-brand-accent text-white' : 'text-slate-400 hover:text-white'}`}
        >
          Bookings
        </button>
        <button 
          onClick={() => setActiveTab('accounts')}
          className={`px-6 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'accounts' ? 'bg-brand-accent text-white' : 'text-slate-400 hover:text-white'}`}
        >
          Inventory
        </button>
      </div>

      {activeTab === 'bookings' && (
        <div className="bg-brand-surface border border-white/10 rounded-xl overflow-hidden overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-brand-dark text-slate-400 text-sm border-b border-white/10">
                <th className="p-4">Order ID</th>
                <th className="p-4">UTR</th>
                <th className="p-4">Account</th>
                <th className="p-4">Duration</th>
                <th className="p-4">Time</th>
                <th className="p-4">Status</th>
                <th className="p-4">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {bookings.length === 0 && (
                <tr>
                   <td colSpan={7} className="p-8 text-center text-slate-500">No bookings yet.</td>
                </tr>
              )}
              {bookings.map(booking => (
                <tr key={booking.orderId} className="hover:bg-white/5 transition-colors">
                  <td className="p-4 font-mono font-bold">{booking.orderId}</td>
                  <td className="p-4 font-mono text-brand-accent">{booking.utr || 'N/A'}</td>
                  <td className="p-4">{booking.accountName}</td>
                  <td className="p-4">{booking.durationLabel}</td>
                  <td className="p-4 text-sm text-slate-400">
                    <div>Start: {new Date(booking.startTime).toLocaleTimeString()}</div>
                    <div>End: {new Date(booking.endTime).toLocaleTimeString()}</div>
                  </td>
                  <td className="p-4">
                    <span className={`px-2 py-1 rounded text-xs font-bold 
                      ${booking.status === BookingStatus.ACTIVE ? 'bg-green-500/20 text-green-400' : 
                        booking.status === BookingStatus.PENDING ? 'bg-yellow-500/20 text-yellow-400' :
                        booking.status === BookingStatus.COMPLETED ? 'bg-slate-500/20 text-slate-400' : 'bg-red-500/20 text-red-400'
                      }`}>
                      {booking.status}
                    </span>
                  </td>
                  <td className="p-4">
                    {booking.status === BookingStatus.PENDING && (
                      <div className="flex gap-2">
                        <button 
                          onClick={() => handleStatusUpdate(booking.orderId, BookingStatus.ACTIVE)}
                          className="p-1 bg-green-600 rounded hover:bg-green-500 text-white" title="Approve"
                        >
                          <Check className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => handleStatusUpdate(booking.orderId, BookingStatus.CANCELLED)}
                          className="p-1 bg-red-600 rounded hover:bg-red-500 text-white" title="Reject"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </div>
                    )}
                    {booking.status === BookingStatus.ACTIVE && (
                       <button 
                        onClick={() => handleStatusUpdate(booking.orderId, BookingStatus.COMPLETED)}
                        className="p-1 bg-blue-600 rounded hover:bg-blue-500 text-white text-xs px-2"
                      >
                        Mark Complete
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'accounts' && (
        <>
          {/* Bulk Actions Toolbar */}
          <div className="flex items-center justify-between mb-4 bg-brand-surface p-3 rounded-lg border border-white/5">
            <div className="flex items-center gap-3">
              <button 
                onClick={handleSelectAll}
                className="flex items-center gap-2 text-sm text-slate-400 hover:text-white transition-colors"
              >
                {selectedIds.size > 0 && selectedIds.size === accounts.length ? (
                  <CheckSquare className="w-5 h-5 text-brand-accent" />
                ) : (
                  <Square className="w-5 h-5" />
                )}
                Select All
              </button>
              {selectedIds.size > 0 && (
                 <span className="text-sm text-white font-bold bg-white/10 px-2 py-0.5 rounded">
                    {selectedIds.size} Selected
                 </span>
              )}
            </div>

            {selectedIds.size > 0 && (
              <button 
                onClick={handleBulkDelete}
                className="flex items-center gap-2 px-4 py-2 bg-red-600/20 text-red-400 border border-red-600/50 rounded-lg hover:bg-red-600 hover:text-white transition-all text-sm font-bold animate-in fade-in slide-in-from-right-2 duration-200"
              >
                <Trash2 className="w-4 h-4" />
                Delete Selected
              </button>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div 
              onClick={() => setShowAddModal(true)}
              className="border-2 border-dashed border-white/10 rounded-xl flex flex-col items-center justify-center min-h-[300px] cursor-pointer hover:border-brand-accent hover:bg-white/5 transition-all group"
            >
              <div className="w-12 h-12 rounded-full bg-brand-dark group-hover:bg-brand-accent flex items-center justify-center transition-colors mb-4">
                <Plus className="w-6 h-6 text-white" />
              </div>
              <span className="font-bold text-lg">Add New ID</span>
            </div>

            {accounts.map(account => (
              <div 
                key={account.id} 
                className={`relative group transition-all duration-200 ${selectedIds.has(account.id) ? 'ring-2 ring-brand-accent transform scale-[1.02] z-10' : ''}`}
                onClick={(e) => {
                  // Allow selecting by clicking anywhere on the card
                  handleToggleSelect(account.id);
                }}
              >
                {/* Reusing card structure broadly, but simplified for admin */}
                <div className="bg-brand-surface border border-white/10 rounded-xl overflow-hidden h-full cursor-pointer">
                  <div className="h-40 bg-gray-800 relative">
                     <img src={account.imageUrl} className="w-full h-full object-cover opacity-50" alt={account.name} />
                     <div className="absolute inset-0 flex items-center justify-center">
                        <span className="font-bold text-xl px-2 text-center drop-shadow-md">{account.name}</span>
                     </div>

                     {/* Selection Checkbox Overlay */}
                     <div className="absolute top-3 left-3 z-40">
                       <button 
                         onClick={(e) => handleToggleSelect(account.id, e)}
                         className={`w-6 h-6 rounded border flex items-center justify-center transition-all ${selectedIds.has(account.id) ? 'bg-brand-accent border-brand-accent text-white' : 'bg-black/50 border-white/30 text-transparent hover:border-white'}`}
                       >
                         <Check className="w-4 h-4" />
                       </button>
                     </div>
                  </div>
                  <div className="p-4 text-sm space-y-2 bg-brand-surface">
                    <div className="flex justify-between border-b border-white/5 pb-2">
                      <span className="text-slate-400">ID:</span>
                      <span className="font-mono text-xs text-slate-500">{account.id}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-400">Status:</span>
                      <span className={`font-bold ${account.isBooked ? 'text-red-400' : 'text-green-400'}`}>{account.isBooked ? 'Booked' : 'Available'}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-400">Rank:</span>
                      <span>{account.rank}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-400">Skins:</span>
                      <span>{account.totalSkins || account.skins.length}</span>
                    </div>
                    <div className="flex justify-between">
