export const StorageService = {
  // Initialize storage if empty
  init: () => {
    if (!localStorage.getItem(ACCOUNTS_KEY)) {
      localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(INITIAL_ACCOUNTS));
    }
    if (!localStorage.getItem(BOOKINGS_KEY)) {
      localStorage.setItem(BOOKINGS_KEY, JSON.stringify([]));
    }
    if (!localStorage.getItem(USERS_KEY)) {
      localStorage.setItem(USERS_KEY, JSON.stringify([]));
    }
  },

  // Account Operations
  getAccounts: (): Account[] => {
    const data = localStorage.getItem(ACCOUNTS_KEY);
    const accounts: Account[] = data ? JSON.parse(data) : [];

    // Auto-update status if booking expired
    const now = new Date();
    const updatedAccounts = accounts.map(acc => {
      if (acc.isBooked && acc.bookedUntil && new Date(acc.bookedUntil) < now) {
        return { ...acc, isBooked: false, bookedUntil: null };
      }
      return acc;
    });

    return updatedAccounts;
  },

  getAccountById: (id: string): Account | undefined => {
    const accounts = StorageService.getAccounts();
    return accounts.find(a => a.id === id);
  },

  saveAccount: (account: Account) => {
    const accounts = StorageService.getAccounts();
    const index = accounts.findIndex(a => a.id === account.id);
    if (index >= 0) {
      accounts[index] = account;
    } else {
      accounts.push(account);
    }
    localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(accounts));
  },

  deleteAccount: (id: string): Account[] => {
    const accounts = StorageService.getAccounts();
    const newAccounts = accounts.filter(a => a.id !== id);
    localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(newAccounts));
    return newAccounts;
  },

  deleteAccounts: (ids: string[]): Account[] => {
    const accounts = StorageService.getAccounts();
    const newAccounts = accounts.filter(a => !ids.includes(a.id));
    localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(newAccounts));
    return newAccounts;
  },

  // Booking Operations
  getBookings: (): Booking[] => {
    const data = localStorage.getItem(BOOKINGS_KEY);
    return data ? JSON.parse(data) : [];
  },

  getUserBookings: (userId: string): Booking[] => {
    const allBookings = StorageService.getBookings();
    return allBookings.filter(b => b.customerId === userId);
  },

  createBooking: (booking: Booking) => {
    const bookings = StorageService.getBookings();
    bookings.unshift(booking); // Add to top
    localStorage.setItem(BOOKINGS_KEY, JSON.stringify(bookings));

    // Update account status
    const accounts = StorageService.getAccounts();
    const accIndex = accounts.findIndex(a => a.id === booking.accountId);
    if (accIndex >= 0) {
      accounts[accIndex].isBooked = true;
      accounts[accIndex].bookedUntil = booking.endTime;
      localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(accounts));
    }
  },

  updateBookingStatus: (orderId: string, status: BookingStatus) => {
    const bookings = StorageService.getBookings();
    const booking = bookings.find(b => b.orderId === orderId);
    if (booking) {
      booking.status = status;
      localStorage.setItem(BOOKINGS_KEY, JSON.stringify(bookings));

      // If completed or cancelled, free up the account
      if (status === BookingStatus.COMPLETED || status === BookingStatus.CANCELLED) {
        const accounts = StorageService.getAccounts();
        const accIndex = accounts.findIndex(a => a.id === booking.accountId);
        if (accIndex >= 0) {
          accounts[accIndex].isBooked = false;
          accounts[accIndex].bookedUntil = null;
          localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(accounts));
        }
      }
    }
  },

  // User / Auth Operations
  getCurrentUser: (): User | null => {
    const data = localStorage.getItem(CURRENT_USER_KEY);
    return data ? JSON.parse(data) : null;
  },

  setCurrentUser: (user: User) => {
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
  },

  logoutUser: () => {
    localStorage.removeItem(CURRENT_USER_KEY);
  },

  // Mock Google Login Logic (Simulating Backend + DB)
  mockGoogleLogin: (): Promise<User> => {
    return new Promise((resolve) => {
      // 1. Simulate Network Delay (1.5s)
      setTimeout(() => {
        // 2. Simulate Data received from Google OAuth Provider
        const mockGoogleProfile = {
          googleId: 'g_' + Math.floor(100000 + Math.random() * 900000),
          email: 'gamer@gmail.com',
          name: 'Google Gamer',
          picture: 'https://lh3.googleusercontent.com/a/default-user=s96-c'
        };

        // 3. Database Logic: Check if user exists, else create
        const usersJSON = localStorage.getItem(USERS_KEY);
        let users: User[] = usersJSON ? JSON.parse(usersJSON) : [];

        let user = users.find(u => u.email === mockGoogleProfile.email); // Simple lookup by email

        const now = new Date().toISOString();

        if (user) {
          // UPDATE EXISTING USER
          user.lastLogin = now;
          // In a real app, we might update avatar or name if changed on Google
          console.log("Welcome back:", user.name);
        } else {
          // CREATE NEW USER
          user = {
            id: 'u_' + Date.now(),
            googleId: mockGoogleProfile.googleId,
            name: mockGoogleProfile.name,
            email: mockGoogleProfile.email,
            avatarUrl: mockGoogleProfile.picture,
            role: 'customer',
            createdAt: now,
            lastLogin: now
          };
          users.push(user);
          console.log("Created new profile:", user.name);
