const Home: React.FC = () => {
  const [config, setConfig] = useState<HomeConfig>(StorageService.getHomeConfig());
  const [selectedVideo, setSelectedVideo] = useState<Review | null>(null);
  const [currentSlide, setCurrentSlide] = useState(0);
  const [activeStep, setActiveStep] = useState(-1);
  const [trustVisible, setTrustVisible] = useState(false);
  const trustRef = useRef<HTMLElement>(null);

  // Reload config on focus (to reflect admin changes immediately if working in tabs)
  useEffect(() => {
    const load = () => setConfig(StorageService.getHomeConfig());
    window.addEventListener('focus', load);
    return () => window.removeEventListener('focus', load);
  }, []);

  // Carousel Auto-Play
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % config.heroSlides.length);
    }, 5000);
    return () => clearInterval(timer);
  }, [config.heroSlides.length]);

  // Trust Section Observer
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setTrustVisible(true);
        }
      },
      { threshold: 0.15 }
    );

    if (trustRef.current) {
      observer.observe(trustRef.current);
    }

    return () => observer.disconnect();
  }, []);

  // Scroll Observer for How It Works steps
  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const index = Number(entry.target.getAttribute('data-index'));
          setActiveStep(index);
        }
      });
    }, { 
      threshold: 0.5, 
