              </div>

              <div>
                <label className="block text-sm text-slate-400 mb-1">Total Skin Count (Optional)</label>
                <input 
                  type="number" 
                  className="w-full bg-brand-dark border border-white/10 rounded p-2 text-white" 
                  value={newAccount.totalSkins || ''} 
                  onChange={e => setNewAccount({...newAccount, totalSkins: e.target.value ? parseInt(e.target.value) : undefined})}
