    const newMarquee = [...homeConfig.marqueeText];
    newMarquee[idx] = text;
    setHomeConfig({ ...homeConfig, marqueeText: newMarquee });
  };

  const addMarqueeItem = () => {
    setHomeConfig({ ...homeConfig, marqueeText: [...homeConfig.marqueeText, "New Item"] });
  };

  const removeMarqueeItem = (idx: number) => {
    const newMarquee = homeConfig.marqueeText.filter((_, i) => i !== idx);
    setHomeConfig({ ...homeConfig, marqueeText: newMarquee });
  };

  const updateHeroSlide = (idx: number, field: keyof HeroSlide, value: string) => {
    const newSlides = [...homeConfig.heroSlides];
    newSlides[idx] = { ...newSlides[idx], [field]: value };
    setHomeConfig({ ...homeConfig, heroSlides: newSlides });
  };

  const updateReview = (idx: number, field: keyof Review, value: string) => {
    const newReviews = [...homeConfig.reviews];
    newReviews[idx] = { ...newReviews[idx], [field]: value };
    setHomeConfig({ ...homeConfig, reviews: newReviews });
