import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Search, X, Sparkles, Command } from 'lucide-react';

const SkinSearchFloatingBar: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [query, setQuery] = useState('');
  const [isFocused, setIsFocused] = useState(false);

  // Sync with URL query param if present
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const q = params.get('q');
    if (q) setQuery(q);
  }, [location.search]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      navigate(`/browse?q=${encodeURIComponent(query.trim())}`);
      setIsFocused(false);
      // Blur input
      const activeElement = document.activeElement as HTMLElement;
      if (activeElement) activeElement.blur();
    }
  };

  const handleClear = () => {
      setQuery('');
      navigate('/browse');
      const input = document.querySelector('input[name="skin-search"]') as HTMLElement;
      if(input) input.focus();
  };

  return (
    <>
        {/* Backdrop when focused */}
        <div 
            className={`fixed inset-0 bg-black/80 backdrop-blur-sm z-40 transition-opacity duration-500 ${isFocused ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
            onClick={() => setIsFocused(false)}
        />

        {/* Floating Bar Container */}
        <div 
            className={`fixed left-0 right-0 mx-auto z-50 transition-all duration-500 ease-out flex justify-center
                ${isFocused 
                    ? 'bottom-[50%] translate-y-[50%] w-full px-4 md:w-[600px]' 
                    : 'bottom-20 md:bottom-8 w-fit pointer-events-none' // pointer-events-none on wrapper to let clicks pass through on sides, but re-enable on child
                }
            `}
        >
            <div className={`pointer-events-auto relative transition-all duration-500 ${!isFocused ? 'animate-float' : ''}`}>
                {/* Glow Effect */}
                <div className={`absolute inset-0 bg-brand-accent/30 rounded-full blur-xl transition-all duration-500 ${isFocused ? 'opacity-70 scale-110' : 'opacity-0 scale-90'}`}></div>

                <form 
                    onSubmit={handleSearch}
                    onClick={() => !isFocused && setIsFocused(true)}
                    className={`relative flex items-center bg-[#0f172a]/90 backdrop-blur-xl border border-white/10 rounded-full shadow-[0_10px_40px_rgba(0,0,0,0.5)] overflow-hidden transition-all duration-500 cursor-text group
                        ${isFocused 
                            ? 'w-full ring-2 ring-brand-cyan/50 py-4 px-6 border-brand-cyan/30' 
                            : 'w-[50px] md:w-[280px] py-3 px-3 md:px-5 hover:border-brand-accent/50 hover:shadow-[0_0_20px_rgba(255,70,85,0.3)]'
                        }
                    `}
                >
                    {/* Search Icon */}
                    <div className={`flex items-center justify-center transition-all duration-300 ${isFocused ? 'mr-4' : 'mr-0 md:mr-3'}`}>
                         <div className={`p-2 rounded-full transition-colors ${isFocused ? 'bg-brand-cyan/20 text-brand-cyan' : 'bg-transparent text-slate-400 group-hover:text-white'}`}>
                             <Search className="w-5 h-5" />
                         </div>
                    </div>

                    {/* Input Field */}
                    <input 
                        name="skin-search"
                        type="text" 
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        onFocus={() => setIsFocused(true)}
                        placeholder="Search IDs by Skin (e.g. Reaver, Prime)..."
                        autoComplete="off"
                        className={`bg-transparent border-none outline-none text-white placeholder-slate-500 font-sans text-base transition-all duration-300
                            ${isFocused 
                                ? 'flex-1 opacity-100' 
                                : 'hidden md:block w-full opacity-100 md:w-48 cursor-text'
                            }
                        `}
                    />

                    {/* Mobile Placeholder Text (when collapsed) */}
                    {!isFocused && (
                        <span className="md:hidden hidden"></span> // Kept hidden, icon only on mobile collapsed
                    )}

                    {/* Actions */}
                    <div className={`flex items-center gap-2 transition-all duration-300 ${isFocused || query ? 'opacity-100 scale-100' : 'opacity-0 scale-0 w-0'}`}>
                        {query && (
                            <button 
                                type="button"
                                onClick={(e) => { e.stopPropagation(); handleClear(); }}
                                className="p-1.5 hover:bg-white/10 rounded-full text-slate-400 hover:text-white transition-colors"
                            >
                                <X className="w-4 h-4" />
                            </button>
                        )}

                        <button 
                            type="submit"
                            className="bg-brand-accent hover:bg-red-600 text-white rounded-full p-2 shadow-[0_0_15px_rgba(255,70,85,0.4)] transition-transform hover:scale-105"
                        >
                            <ArrowRightIcon className="w-4 h-4" />
                        </button>
                    </div>

                    {/* Animated Border Gradient Bottom */}
                    <div className="absolute bottom-0 left-0 h-[1px] bg-gradient-to-r from-transparent via-brand-cyan to-transparent w-full opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
                </form>
            </div>
        </div>
    </>
  );
};

const ArrowRightIcon = ({ className }: { className?: string }) => (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
        <path d="M5 12h14" />
        <path d="m12 5 7 7-7 7" />
    </svg>
);

export default SkinSearchFloatingBar;

