  const [showBookingModal, setShowBookingModal] = useState(false);
  const [isImageModalOpen, setIsImageModalOpen] = useState(false);

  // Booking Wizard State
  const [step, setStep] = useState<1 | 2>(1);
  const [selectedDuration, setSelectedDuration] = useState<keyof Pricing>('hours3');
  const [startMode, setStartMode] = useState<'now' | 'later'>('now');
  const [scheduledTime, setScheduledTime] = useState('');

  useEffect(() => {
    if (id) {
      const acc = StorageService.getAccountById(id);
      setAccount(acc);
    }
  }, [id]);

  useEffect(() => {
     window.scrollTo(0, 0);
  }, []);

  if (!account) {
    return (
      <div className="min-h-[50vh] flex flex-col items-center justify-center">
        <h2 className="text-2xl font-bold text-white mb-4">Account Not Found</h2>
        <Link to="/browse" className="text-brand-accent hover:underline flex items-center gap-2">
           <ArrowLeft className="w-4 h-4" /> Back to Browse
        </Link>
      </div>
    );
  }

  const isAvailable = !account.isBooked;

  // --- Wizard Logic ---

  const getMinDateTime = () => {
    const now = new Date();
    now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
    return now.toISOString().slice(0, 16);
  };

  const calculateTimes = () => {
    if (!selectedDuration) return { start: null, end: null };
    const hours = selectedDuration === 'hours3' ? 3 : selectedDuration === 'hours12' ? 12 : 24;
    let start = new Date();
    if (startMode === 'later' && scheduledTime) {
      start = new Date(scheduledTime);
    }
    const end = new Date(start.getTime() + hours * 60 * 60 * 1000);
    return { start, end };
  };

  const formatTime12Hour = (date: Date | null) => {
    if (!date) return '--:--';
    return date.toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit', hour12: true });
  };

  const handleProceedToCheckout = () => {
    if (!account) return;

    if (startMode === 'later' && !scheduledTime) {
      alert("Please select a date and time for your booking.");
      return;
    }
    if (startMode === 'later') {
      const selectedDate = new Date(scheduledTime);
      if (selectedDate < new Date()) {
         alert("Please select a future time.");
         return;
      }
    }

    const hours = selectedDuration === 'hours3' ? 3 : selectedDuration === 'hours12' ? 12 : 24;
    const basePrice = account.pricing[selectedDuration];
    const isDiscounted = selectedDuration === 'hours24';
    const finalPrice = isDiscounted ? Math.floor(basePrice * 0.9) : basePrice;

    const user = StorageService.getCurrentUser();
    const checkoutState = { 
      account: account,
      hours,
      price: finalPrice,
      originalPrice: isDiscounted ? basePrice : undefined,
      durationLabel: selectedDuration === 'hours3' ? '3 Hours' : selectedDuration === 'hours12' ? '12 Hours' : '24 Hours',
      startMode,
      scheduledTime: startMode === 'later' ? scheduledTime : undefined
    };

    if (!user) {
      navigate('/login', { state: { returnTo: '/checkout', checkoutState } });
    } else {
      navigate('/checkout', { state: checkoutState });
    }
  };

  const { start, end } = calculateTimes();
  const currentPrice = account.pricing[selectedDuration];
  const is24h = selectedDuration === 'hours24';
  const displayPriceStep2 = is24h ? Math.floor(currentPrice * 0.9) : currentPrice;

  // WhatsApp Link
  const waMessage = `I am interested in buying the account: ${account.name} (Rank: ${account.rank}). What is the buying price?`;
  const waLink = `https://wa.me/919860185116?text=${encodeURIComponent(waMessage)}`;

  // Modals Content
  const ImageModal = (
     <div 
        className="fixed inset-0 z-[200] bg-black/95 backdrop-blur-xl flex items-center justify-center p-4 animate-in fade-in duration-200"
        onClick={() => setIsImageModalOpen(false)}
     >
        <button 
           onClick={() => setIsImageModalOpen(false)}
           className="absolute top-6 right-6 p-3 bg-white/10 hover:bg-red-500/50 rounded-full text-white transition-all z-[210] group"
        >
           <X className="w-8 h-8 group-hover:scale-110 transition-transform" />
        </button>

        <img 
           src={account.imageUrl} 
           alt={account.name} 
           className="max-w-full max-h-full object-contain rounded-lg shadow-2xl"
           onClick={(e) => e.stopPropagation()} // Prevent closing when clicking the image
        />
     </div>
  );

  const BookingModal = (
     <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
        <div className="bg-brand-surface border border-white/10 rounded-2xl w-full max-w-md overflow-hidden shadow-2xl animate-in fade-in zoom-in duration-200 flex flex-col max-h-[90vh] relative z-[210]">
           {/* Header */}
           <div className="p-4 border-b border-white/10 flex justify-between items-center bg-brand-dark/50 shrink-0">
              <div className="flex items-center gap-2">
                 {step === 2 && (
                    <button onClick={() => setStep(1)} className="mr-1 p-1 hover:bg-white/10 rounded-full transition-colors">
                       <ArrowLeft className="w-5 h-5 text-slate-300" />
                    </button>
                 )}
                 <h3 className="font-bold text-lg">{step === 1 ? 'Select Duration' : 'Select Time'}</h3>
              </div>
              <button onClick={() => { setShowBookingModal(false); setStep(1); }} className="text-slate-400 hover:text-white transition-colors">
                 <X className="w-6 h-6" />
              </button>
           </div>

           {/* Step 1: Duration */}
           {step === 1 && (
              <div className="p-6 overflow-y-auto">
                 <div className="space-y-3 mb-8">
                    {[
                       { id: 'hours3', label: '3 Hours', price: account.pricing.hours3 },
                       { id: 'hours12', label: '12 Hours', price: account.pricing.hours12 },
                       { id: 'hours24', label: '24 Hours', price: account.pricing.hours24 },
                    ].map((option) => {
                       const isDiscounted = option.id === 'hours24';
                       const finalPrice = isDiscounted ? Math.floor(option.price * 0.9) : option.price;
                       return (
                          <div key={option.id} onClick={() => setSelectedDuration(option.id as keyof Pricing)}
                             className={`flex items-center justify-between p-4 rounded-xl border cursor-pointer transition-all ${selectedDuration === option.id ? 'border-brand-accent bg-brand-accent/10 shadow-[0_0_15px_rgba(255,70,85,0.1)]' : 'border-white/10 bg-brand-dark hover:bg-white/5'}`}
                          >
                             <div className="flex items-center gap-3">
                                <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${selectedDuration === option.id ? 'border-brand-accent' : 'border-slate-500'}`}>
                                   {selectedDuration === option.id && <div className="w-2.5 h-2.5 rounded-full bg-brand-accent" />}
                                </div>
                                <div>
                                   <span className="font-medium text-white text-lg">{option.label}</span>
                                   {isDiscounted && <span className="ml-2 bg-brand-accent text-white text-[10px] px-1.5 py-0.5 rounded font-bold">SAVE 10%</span>}
                                </div>
                             </div>
                             <div className="text-right">
                                {isDiscounted && <div className="text-xs text-slate-500 line-through">₹{option.price}</div>}
                                <span className="font-bold text-xl text-brand-accent">₹{finalPrice}</span>
                             </div>
                          </div>
                       )
                    })}
                 </div>
                 <button onClick={() => setStep(2)} className="w-full bg-brand-accent hover:bg-red-600 text-white font-bold py-4 rounded-lg flex items-center justify-center gap-2">
                    Next Step <ChevronRight className="w-5 h-5" />
                 </button>
              </div>
           )}

           {/* Step 2: Time */}
           {step === 2 && (
              <div className="p-6 overflow-y-auto">
                 <div className="bg-brand-dark border border-white/10 rounded-lg p-3 flex justify-between items-center mb-6">
                    <div>
                       <span className="text-xs text-slate-500 uppercase">Total</span>
                       <div className="font-bold text-white text-xl">₹{displayPriceStep2}</div>
                    </div>
                    <div className="text-right text-sm text-slate-300">{selectedDuration === 'hours3' ? '3 Hours' : selectedDuration === 'hours12' ? '12 Hours' : '24 Hours'}</div>
                 </div>

                 <div className="mb-6">
                    <label className="text-sm text-slate-400 font-medium mb-3 block">Start Time</label>
                    <div className="grid grid-cols-2 gap-3 mb-4">
                       <button onClick={() => setStartMode('now')} className={`py-3 px-2 text-sm font-bold rounded-xl border flex flex-col items-center gap-2 ${startMode === 'now' ? 'bg-brand-accent border-brand-accent text-white' : 'bg-brand-dark border-white/10 text-slate-400'}`}>
                          <Clock className="w-5 h-5" /> Start Now
                       </button>
                       <button onClick={() => setStartMode('later')} className={`py-3 px-2 text-sm font-bold rounded-xl border flex flex-col items-center gap-2 ${startMode === 'later' ? 'bg-brand-accent border-brand-accent text-white' : 'bg-brand-dark border-white/10 text-slate-400'}`}>
                          <Calendar className="w-5 h-5" /> Schedule
                       </button>
                    </div>

                    {startMode === 'later' && (
                       <div className="mb-4">
                          <input type="datetime-local" min={getMinDateTime()} value={scheduledTime} onChange={(e) => setScheduledTime(e.target.value)} className="w-full bg-brand-dark border border-white/10 rounded-lg px-4 py-3 text-white [color-scheme:dark]" />
                       </div>
                    )}

                    <div className="bg-gradient-to-br from-brand-dark to-brand-surface border border-white/10 rounded-xl p-4 text-center">
                       <div className="flex items-center justify-between gap-2">
                          <div>
                             <div className="text-xl font-bold text-white">{startMode === 'now' ? 'Now' : formatTime12Hour(start)}</div>
                             <div className="text-[10px] text-slate-500 uppercase font-bold">Start</div>
                          </div>
                          <ArrowRight className="w-4 h-4 text-brand-accent" />
                          <div>
                             <div className="text-xl font-bold text-brand-accent">{formatTime12Hour(end)}</div>
                             <div className="text-[10px] text-slate-500 uppercase font-bold">End</div>
                          </div>
                       </div>
                    </div>
                 </div>

                 <button onClick={handleProceedToCheckout} className="w-full bg-brand-accent hover:bg-red-600 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2">
                    {!StorageService.getCurrentUser() && <Lock className="w-4 h-4" />}
                    {StorageService.getCurrentUser() ? 'Proceed to Payment' : 'Login to Proceed'}
                 </button>
              </div>
           )}
        </div>
     </div>
  );

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      {/* Back Nav */}
      <Link to="/browse" className="inline-flex items-center gap-2 text-slate-400 hover:text-white mb-6 transition-colors group">
         <div className="p-2 rounded-full bg-white/5 group-hover:bg-white/10">
            <ArrowLeft className="w-4 h-4" />
         </div>
         <span className="font-bold text-sm uppercase tracking-wide">Back to Inventory</span>
      </Link>

      <div className="grid lg:grid-cols-2 gap-10">

         {/* Left Column: Image & Visuals */}
         <div className="space-y-6">
            <div 
               className="relative rounded-xl overflow-hidden border border-white/10 bg-brand-dark group cursor-zoom-in shadow-lg shadow-black/50"
               onClick={() => setIsImageModalOpen(true)}
            >
               <img src={account.imageUrl} alt={account.name} className="w-full aspect-video object-cover transition-transform duration-700 group-hover:scale-105" />
               <div className="absolute inset-0 bg-gradient-to-t from-brand-dark via-transparent to-transparent opacity-80" />

               {/* Hover Hint */}
               <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/20 pointer-events-none">
                  <div className="bg-black/60 backdrop-blur-md p-3 rounded-full border border-white/20">
                     <Maximize2 className="w-8 h-8 text-white" />
                  </div>
               </div>

               <div className="absolute top-4 right-4">
                  {isAvailable ? (
                     <div className="px-4 py-2 bg-green-500/10 border border-green-500/20 backdrop-blur-md rounded-lg text-green-400 font-bold flex items-center gap-2 uppercase text-sm">
                        <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                        Available Now
                     </div>
                  ) : (
                     <div className="px-4 py-2 bg-red-500/10 border border-red-500/20 backdrop-blur-md rounded-lg text-red-400 font-bold flex items-center gap-2 uppercase text-sm">
                        <Clock className="w-4 h-4" />
                        Booked
                     </div>
                  )}
               </div>
            </div>

            {/* Skin Showcase Grid */}
            <div>
               <h3 className="text-lg font-bold text-white mb-3 flex items-center gap-2">
                  <Gem className="w-5 h-5 text-brand-cyan" />
                  Premium Collection <span className="text-xs bg-white/10 px-2 py-0.5 rounded text-slate-400">{account.totalSkins || account.skins.length} Skins</span>
               </h3>
               <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                  {account.skins.map((skin, idx) => (
                     <div key={idx} className="bg-brand-surface border border-white/5 p-3 rounded-lg text-sm text-slate-300 hover:border-brand-accent/30 hover:text-white transition-all cursor-default">
                        {skin}
                     </div>
                  ))}
               </div>
            </div>
         </div>

         {/* Right Column: Details & Actions */}
         <div className="space-y-8">
            <div>
               <div className="flex items-center gap-3 mb-2">
                  <span className={`px-3 py-1 rounded text-xs font-bold uppercase border bg-opacity-10
                     ${account.rank.includes('Immortal') ? 'border-red-500 bg-red-500 text-red-400' : 
                       account.rank.includes('Ascendant') ? 'border-emerald-500 bg-emerald-500 text-emerald-400' :
                       'border-brand-cyan bg-brand-cyan text-brand-cyan'}`}
                  >
                     {account.rank}
                  </span>
                  <span className="text-slate-500 text-xs uppercase tracking-widest font-mono">ID: {account.id}</span>
               </div>
               <h1 className="text-4xl font-display font-bold text-white mb-4">{account.name}</h1>
               {/* Description text removed as per user request (strike-through in image) */}
            </div>

            {/* Pricing Section - Clickable to open modal */}
            <div className="bg-brand-surface border border-white/10 rounded-xl p-6">
               <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4">Rental Rates</h3>
               <div className="grid grid-cols-3 gap-4">
                  {[
                     { id: 'hours3', label: '3 Hours', price: account.pricing.hours3 },
                     { id: 'hours12', label: '12 Hours', price: account.pricing.hours12 },
                     { id: 'hours24', label: '24 Hours', price: account.pricing.hours24, discount: true }
                  ].map((plan, idx) => (
                     <button 
                        key={idx} 
                        onClick={() => { 
                           if(isAvailable) {
                              setSelectedDuration(plan.id as keyof Pricing);
                              setStep(1);
                              setShowBookingModal(true);
                           }
                        }}
                        disabled={!isAvailable}
                        className={`relative p-4 rounded-lg border text-center transition-all duration-200 
                           ${plan.discount ? 'bg-brand-accent/5 border-brand-accent/30 hover:bg-brand-accent/10' : 'bg-brand-dark border-white/5 hover:bg-white/5'}
                           ${isAvailable ? 'cursor-pointer hover:border-brand-cyan/50 hover:shadow-[0_0_15px_rgba(0,240,255,0.2)]' : 'cursor-not-allowed opacity-50'}
                        `}
                     >
                        {plan.discount && (
                           <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-brand-accent text-white text-[10px] font-bold px-2 py-0.5 rounded-full shadow-lg">
                              BEST VALUE
                           </div>
                        )}
                        <div className="text-xs text-slate-500 uppercase mb-1">{plan.label}</div>
                        <div className="text-xl font-bold text-white">
                           ₹{plan.discount ? Math.floor(plan.price * 0.9) : plan.price}
                        </div>
                     </button>
                  ))}
               </div>
            </div>

            {/* Action Buttons */}
            <div className="space-y-3">
               <button 
                  onClick={() => isAvailable && setShowBookingModal(true)}
                  disabled={!isAvailable}
                  className={`w-full py-4 text-lg font-bold uppercase tracking-wider rounded-lg shadow-lg flex items-center justify-center gap-2 transition-all hover:scale-[1.02]
                     ${isAvailable 
                        ? 'bg-white text-brand-darker hover:bg-brand-accent hover:text-white shadow-brand-accent/20' 
                        : 'bg-slate-800 text-slate-500 cursor-not-allowed'}`}
               >
                  {isAvailable ? 'Rent Now' : 'Currently Unavailable'} 
                  {isAvailable && <ArrowRight className="w-5 h-5" />}
               </button>

               <a 
                  href={waLink}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="w-full py-4 text-sm font-bold uppercase tracking-wider rounded-lg border border-green-500/30 text-green-400 hover:bg-green-500/10 flex items-center justify-center gap-2 transition-all hover:border-green-500"
               >
                  <MessageCircle className="w-5 h-5" />
                  Buy Now? Chat with our expert
               </a>
            </div>
         </div>
      </div>

      {/* Render Modals via Portal */}
      {isImageModalOpen && createPortal(ImageModal, document.body)}
      {showBookingModal && createPortal(BookingModal, document.body)}

    </div>
  );
};

