  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');

  const navigate = useNavigate();
  const location = useLocation();

  const { returnTo, checkoutState } = location.state || {};

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (isVerifying) {
        await StorageService.verifyUser(verifyEmail, verificationCode);
        navigateAfterAuth();
      } else if (isRegistering) {
        if (!name || !email || !phone || !password) {
           throw new Error("All fields are required");
        }
        const result = await StorageService.registerUser(name, email, phone, password);
        // Mocking an email send - in a real app, the server would send the email.
        alert(`MOCK EMAIL SENT TO ${email}: Your verification code is ${result.code}`);
        setVerifyEmail(email);
        setIsVerifying(true);
        setLoading(false);
      } else {
        if (!email || !password) {
           throw new Error("Please enter email and password");
        }
        await StorageService.loginUser(email, password);
        navigateAfterAuth();
      }
    } catch (err: any) {
      if (err === "EMAIL_NOT_VERIFIED") {
        setVerifyEmail(email);
        setIsVerifying(true);
        setError("Please verify your email to continue.");
      } else {
        setError(err.message || (typeof err === 'string' ? err : 'Authentication failed'));
      }
      setLoading(false);
    }
  };

  const navigateAfterAuth = () => {
    if (returnTo && checkoutState) {
      navigate(returnTo, { state: checkoutState });
    } else {
      navigate('/');
    }
  };

  const handleGuestBrowsing = () => {
    navigate('/browse');
  };

  return (
