                       <div key={idx} className="bg-brand-dark/50 border border-white/5 p-3 rounded-xl text-[11px] text-slate-300 font-medium hover:border-brand-accent/20 transition-all cursor-default animate-in fade-in duration-300">
                          {skin}
                       </div>
                    ))}
                  </div>

