                  </div>
                  <span className="font-display font-bold text-xl md:text-3xl tracking-wide text-white group-hover:text-transparent group-hover:bg-clip-text group-hover:bg-gradient-to-r group-hover:from-white group-hover:to-brand-cyan transition-all whitespace-nowrap">
