             </div>
             <span className="mt-8 text-[10px] font-bold text-slate-500 group-hover:text-white">RENT</span>
          </Link>

          {currentUser ? (
             <Link to="/dashboard" className="relative flex flex-col items-center justify-center w-full h-full gap-1 group">
