import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Search, X, ArrowRight } from 'lucide-react';

interface SkinSearchFloatingBarProps {
  isHomePage: boolean;
}

const SkinSearchFloatingBar: React.FC<SkinSearchFloatingBarProps> = ({ isHomePage }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const [query, setQuery] = useState('');
  const [isFocused, setIsFocused] = useState(false);

  // Sync with URL query param if present
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const q = params.get('q');
    if (q) setQuery(q);
  }, [location.search]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      navigate(`/browse?q=${encodeURIComponent(query.trim())}`);
      setIsFocused(false);
      // Blur input
      const activeElement = document.activeElement as HTMLElement;
      if (activeElement) activeElement.blur();
    }
  };

  const handleClear = () => {
      setQuery('');
      navigate('/browse');
      const input = document.querySelector('input[name="skin-search"]') as HTMLElement;
      if(input) input.focus();
  };

  // Determine visual mode
  const mode = isHomePage ? 'hero' : 'header';

  return (
    <>
        {/* Backdrop when focused */}
        <div 
            className={`fixed inset-0 bg-black/80 backdrop-blur-sm z-[55] transition-opacity duration-500 ${isFocused ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
            onClick={() => setIsFocused(false)}
        />

        {/* Floating Bar Container */}
        <div 
            className={`fixed z-[60] transition-all duration-700 ease-[cubic-bezier(0.34,1.56,0.64,1)] 
                ${isFocused 
                    ? 'top-32 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] md:w-[600px] px-0' 
                    : mode === 'hero'
                        ? 'top-36 left-1/2 -translate-x-1/2 w-fit'
                        : 'top-3 right-3 md:right-8 md:top-3.5 w-fit translate-x-0'
                }
            `}
        >
            <div className={`transition-all duration-500 ${!isFocused && mode === 'hero' ? 'animate-float' : ''}`}>
                {/* Glow Effect */}
                <div className={`absolute inset-0 bg-brand-accent/30 rounded-full blur-xl transition-all duration-500 ${isFocused ? 'opacity-70 scale-110' : 'opacity-0 scale-90'}`}></div>

                <form 
                    onSubmit={handleSearch}
                    onClick={() => !isFocused && setIsFocused(true)}
                    className={`relative flex items-center bg-[#0f172a]/90 backdrop-blur-xl border border-white/10 rounded-full shadow-[0_10px_40px_rgba(0,0,0,0.5)] overflow-hidden transition-all duration-500 cursor-text group
                        ${isFocused 
                            ? 'w-full ring-2 ring-brand-cyan/50 py-4 px-6 border-brand-cyan/30' 
                            : mode === 'hero'
                                ? 'w-[50px] md:w-[280px] py-3 px-3 md:px-5 hover:border-brand-accent/50 hover:shadow-[0_0_20px_rgba(255,70,85,0.3)]'
                                : 'w-[42px] h-[42px] md:w-[46px] md:h-[46px] py-0 px-0 justify-center hover:bg-white/10 border-white/5'
                        }
                    `}
                >
                    {/* Search Icon */}
                    <div className={`flex items-center justify-center transition-all duration-300 ${isFocused ? 'mr-4' : (mode === 'hero' ? 'mr-0 md:mr-3' : 'mr-0')}`}>
                         <div className={`transition-colors p-2 rounded-full ${isFocused ? 'bg-brand-cyan/20 text-brand-cyan' : 'bg-transparent text-slate-400 group-hover:text-white'}`}>
                             <Search className={`${mode === 'header' && !isFocused ? 'w-5 h-5 md:w-6 h-6' : 'w-5 h-5'}`} />
                         </div>
                    </div>

                    {/* Input Field */}
                    <input 
                        name="skin-search"
                        type="text" 
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        onFocus={() => setIsFocused(true)}
                        placeholder="Search Skins..."
                        autoComplete="off"
                        className={`bg-transparent border-none outline-none text-white placeholder-slate-500 font-sans text-base transition-all duration-500
                            ${isFocused 
                                ? 'flex-1 opacity-100' 
                                : mode === 'hero'
                                    ? 'hidden md:block w-full opacity-100 md:w-48 cursor-text'
                                    : 'hidden'
                            }
                        `}
                    />

                    {/* Actions */}
                    <div className={`flex items-center gap-2 transition-all duration-300 ${isFocused || (mode === 'hero' && query) ? 'opacity-100 scale-100' : 'opacity-0 scale-0 w-0'}`}>
                        {query && isFocused && (
                            <button 
                                type="button"
                                onClick={(e) => { e.stopPropagation(); handleClear(); }}
                                className="p-1.5 hover:bg-white/10 rounded-full text-slate-400 hover:text-white transition-colors"
                            >
                                <X className="w-4 h-4" />
                            </button>
                        )}

                        {isFocused && (
                            <button 
                                type="submit"
                                className="bg-brand-accent hover:bg-red-600 text-white rounded-full p-2 shadow-[0_0_15px_rgba(255,70,85,0.4)] transition-transform hover:scale-105"
                            >
                                <ArrowRight className="w-4 h-4" />
                            </button>
                        )}
                    </div>

                    {/* Animated Border Gradient Bottom */}
                    <div className={`absolute bottom-0 left-0 h-[1px] bg-gradient-to-r from-transparent via-brand-cyan to-transparent w-full transition-opacity duration-500 ${isFocused ? 'opacity-100' : 'opacity-0'}`}></div>
                </form>
            </div>
        </div>
    </>
  );
};

export default SkinSearchFloatingBar;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Search, X, ArrowRight } from 'lucide-react';

interface SkinSearchFloatingBarProps {
  isHomePage: boolean;
}

const SkinSearchFloatingBar: React.FC<SkinSearchFloatingBarProps> = ({ isHomePage }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const [query, setQuery] = useState('');
  const [isFocused, setIsFocused] = useState(false);
  const [arrivalPulse, setArrivalPulse] = useState(false);
  const prevIsHome = useRef(isHomePage);

  // Trigger a pulse effect when the bar finishes docking into the header
  useEffect(() => {
    if (prevIsHome.current && !isHomePage) {
      setArrivalPulse(true);
      const timer = setTimeout(() => setArrivalPulse(false), 1000);
      return () => clearTimeout(timer);
    }
    prevIsHome.current = isHomePage;
  }, [isHomePage]);

  // Sync with URL query param if present
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const q = params.get('q');
    if (q) setQuery(q);
  }, [location.search]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      navigate(`/browse?q=${encodeURIComponent(query.trim())}`);
      setIsFocused(false);
      const activeElement = document.activeElement as HTMLElement;
      if (activeElement) activeElement.blur();
    }
  };

  const handleClear = () => {
      setQuery('');
      navigate('/browse');
  };

  const mode = isHomePage ? 'hero' : 'header';

  return (
    <>
        {/* Backdrop - Only when focused */}
        <div 
            className={`fixed inset-0 bg-black/60 backdrop-blur-[6px] z-[55] transition-all duration-700 ${isFocused ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
            onClick={() => setIsFocused(false)}
