          ))}
        </div>
      </div>
      <div className="flex gap-4 mt-6">
        <button onClick={onAdd} disabled={isSubmitting} className="flex-1 bg-brand-accent py-3 rounded font-bold text-white">{isSubmitting ? 'Adding...' : 'Add Account'}</button>
