        onClose={() => setShowAddModal(false)} 
        onAdd={handleAddAccount} 
        skinInput={skinInput} 
        setSkinInput={setSkinInput} 
        addSkin={() => {
          if(skinInput) {
            setNewAccount({...newAccount, skins: [...(newAccount.skins || []), { name: skinInput, isHighlighted: false }]});
