            <rect 
              x="0" 
              y="0" 
              width={filled ? "100" : "0"} 
              height="100" 
              className="transition-all duration-1000 ease-in-out"
              fill="url(#liquid-gradient)"
            />
         </g>
         <defs>
           <linearGradient id="liquid-gradient" x1="0%" y1="0%" x2="100%" y2="0%">
