           {(config.marqueeText || []).map((text, i) => (
             <React.Fragment key={i}>
               <span>{text}</span>
               <span className="text-white opacity-30">•</span>
             </React.Fragment>
           ))}
        </div>
      </div>

      {/* Advanced Hero Carousel Section */}
