import { ChevronRight, Gamepad2, Clock, QrCode, MessageCircle, Play, Star, Zap, Shield, TrendingUp, CheckCircle2, Loader2, MousePointer2 } from 'lucide-react';
import CustomVideoPlayer from '../components/CustomVideoPlayer';
import { StorageService, DEFAULT_HOME_CONFIG } from '../services/storage';
import { HomeConfig, Review } from '../types';

const Home: React.FC = () => {
  const [config, setConfig] = useState<HomeConfig>(DEFAULT_HOME_CONFIG);
  const [loading, setLoading] = useState(true);
  const [selectedVideo, setSelectedVideo] = useState<Review | null>(null);
  const [currentSlide, setCurrentSlide] = useState(0);

  // Scroll Trigger State
  const procedureRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);

  const loadConfig = async () => {
    try {
      const data = await StorageService.getHomeConfig();
      setConfig(data);
    } catch (err) {
      console.error("Home load error:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadConfig();
    window.addEventListener('storage', loadConfig);
    return () => window.removeEventListener('storage', loadConfig);
  }, []);

  // Intersection Observer for generic entrance animations
  useEffect(() => {
    if (loading) return;

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
        }
      });
    }, { threshold: 0.15, rootMargin: '0px 0px -50px 0px' });

    const animatedElements = document.querySelectorAll('.animate-on-scroll');
    animatedElements.forEach(el => observer.observe(el));

    return () => observer.disconnect();
  }, [loading, config]);

  // Scroll Progress Logic for the Procedure Section
  useEffect(() => {
    const handleScroll = () => {
      if (!procedureRef.current) return;

      const rect = procedureRef.current.getBoundingClientRect();
      const windowHeight = window.innerHeight;

      // Calculate progress: 0 when top enters bottom of screen, 1 when bottom leaves top
      // We want the progress to start when the section is centered
      const start = rect.top - windowHeight * 0.2;
      const end = rect.height;
      const progress = Math.min(Math.max(-start / end, 0), 1);

      setScrollProgress(progress);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [loading]);

  useEffect(() => {
    if (!config || !config.heroSlides || config.heroSlides.length === 0) return;
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % config.heroSlides.length);
    }, 6000);
    return () => clearInterval(timer);
  }, [config.heroSlides?.length]);

  if (loading) {
    return (
      <div className="h-[650px] flex items-center justify-center bg-brand-dark">
         <div className="flex flex-col items-center gap-4">
            <Loader2 className="w-12 h-12 text-brand-accent animate-spin" />
            <p className="text-slate-500 font-mono text-xs uppercase tracking-widest">Establishing Secure Uplink...</p>
         </div>
      </div>
    );
  }

  const trustIcons = [Zap, Shield, TrendingUp, Star];
  const stepIcons = [Gamepad2, Clock, QrCode, MessageCircle];

  return (
    <div className="flex flex-col overflow-hidden">

      {/* Marquee Header */}
      <div className="bg-brand-accent/20 border-b border-brand-accent/30 py-1.5 overflow-hidden backdrop-blur-md relative z-20">
        <div className="animate-marquee whitespace-nowrap flex gap-12 text-xs font-bold font-mono tracking-widest text-brand-cyan">
           {(config.marqueeText || []).map((text, i) => (
             <React.Fragment key={i}>
               <span>{text}</span>
               <span className="text-white opacity-30">•</span>
             </React.Fragment>
           ))}
        </div>
      </div>

      {/* Hero Section */}
      <section className="relative h-[720px] md:h-[800px] lg:h-[900px] flex items-center justify-center overflow-hidden group bg-black">
        <div className="absolute inset-0 z-0 opacity-20 hero-grid animate-grid-pan pointer-events-none"></div>
        {(config.heroSlides || []).map((slide, index) => (
          <div 
            key={slide.id}
            className={`absolute inset-0 transition-opacity duration-1000 ease-in-out ${index === currentSlide ? 'opacity-100' : 'opacity-0'}`}
          >
            <div className="absolute inset-0 bg-black/50 z-10" />
            <div className="absolute inset-0 bg-gradient-to-t from-brand-darker via-transparent to-brand-darker/40 z-10" />
            <img src={slide.image} alt="Hero" className={`w-full h-full object-cover transition-transform duration-[12000ms] ease-out ${index === currentSlide ? 'scale-110' : 'scale-100 opacity-0'}`} />
          </div>
        ))}

        <div key={`content-${currentSlide}`} className="relative z-30 text-center px-4 max-w-5xl mx-auto">
          <div className="mb-6 md:mb-10 inline-flex items-center gap-1.5 md:gap-3 px-3 md:px-6 py-1.5 md:py-2 rounded-full border border-white/10 bg-black/40 backdrop-blur-xl animate-reveal-up shadow-[0_0_25px_rgba(255,255,255,0.08)]">
             <div className="w-2 h-2 md:w-2.5 md:h-2.5 rounded-full bg-brand-cyan animate-pulse shadow-[0_0_15px_#00f0ff]"></div>
             <span className="text-[10px] md:text-[13px] font-bold tracking-[0.2em] md:tracking-[0.5em] text-white">SYSTEM ONLINE // AGENT_VERIFIED</span>
          </div>
          <h1 className="text-5xl md:text-8xl lg:text-[10rem] font-display font-black text-white mb-8 md:mb-12 tracking-tighter leading-[0.85] uppercase animate-reveal-up" style={{ animationDelay: '0.15s' }}>
             <span className={`glitch-text block transition-colors duration-1000 ${config.heroSlides?.[currentSlide]?.accent || 'text-white'}`} data-text={config.heroSlides?.[currentSlide]?.title}>
               {config.heroSlides?.[currentSlide]?.title}
             </span>
          </h1>
          <p className="text-lg md:text-3xl lg:text-4xl text-slate-300 mb-12 max-w-4xl mx-auto font-light tracking-[0.15em] border-l-4 border-brand-accent pl-6 md:pl-10 text-left md:text-center md:border-l-0 md:pl-0 animate-reveal-up opacity-0 fill-mode-forwards" style={{ animationDelay: '0.3s' }}>
            {config.heroSlides?.[currentSlide]?.subtitle}
          </p>
          <div className="flex flex-col sm:flex-row gap-8 justify-center items-center animate-reveal-up opacity-0 fill-mode-forwards" style={{ animationDelay: '0.45s' }}>
            <Link to="/browse" className={`relative overflow-hidden group/btn px-8 py-3.5 md:px-16 md:py-6 ${config.heroSlides?.[currentSlide]?.buttonColor || 'bg-brand-accent'} font-black rounded-none skew-x-[-12deg] uppercase tracking-[0.3em] transition-all shadow-[0_0_40px_rgba(0,0,0,0.5)] hover:shadow-[0_0_60px_rgba(255,70,85,0.4)] hover:scale-105 flex items-center gap-4`}>
              <div className="absolute inset-0 z-0 bg-gradient-to-r from-transparent via-white/40 to-transparent w-full h-full animate-shimmer opacity-20 pointer-events-none"></div>
              <div className="skew-x-[12deg] relative z-10 flex items-center gap-4 text-white text-base md:text-2xl">
                START OPERATION <ChevronRight className="w-5 h-5 md:w-8 md:h-8 group-hover/btn:translate-x-2 transition-transform duration-500" />
              </div>
            </Link>
          </div>
        </div>
      </section>

      {/* Trust Indicators */}
      <section className="bg-brand-darker border-y border-white/5 py-24 relative overflow-visible">
        <div className="max-w-7xl mx-auto px-4 grid grid-cols-2 md:grid-cols-4 gap-6 relative z-10">
          {(config.trustItems || []).map((item, i) => {
            const Icon = trustIcons[i % trustIcons.length] || Star;
            return (
             <div key={i} className="animate-on-scroll glass-panel p-8 rounded-2xl flex flex-col items-center gap-4 hover:bg-white/5 group border border-white/5 transition-all" style={{ transitionDelay: `${i * 150}ms` }}>
                <Icon className={`w-10 h-10 text-brand-cyan group-hover:scale-110 transition-transform group-hover:drop-shadow-[0_0_10px_#00f0ff]`} />
                <div className="text-center">
                  <div className="font-display font-bold text-2xl text-white uppercase tracking-tight">{item.label}</div>
                  <div className="text-[10px] font-mono text-slate-500 uppercase tracking-[0.3em] mt-1">{item.sub}</div>
                </div>
             </div>
          )})}
        </div>
      </section>

      {/* Operation Procedure - SCROLL TRIGGER RE-ENGINEERED */}
      <section ref={procedureRef} id="how-it-works" className="relative py-48 bg-black overflow-hidden">
        {/* Parallax Background Grid */}
        <div 
          className="absolute inset-0 opacity-10 pointer-events-none hero-grid transition-transform duration-300" 
          style={{ transform: `translateY(${scrollProgress * 100}px)` }}
        ></div>

        <div className="max-w-7xl mx-auto px-4 relative z-10">
          <div className="text-center mb-32 animate-on-scroll">
            <h2 className="text-5xl md:text-8xl font-display font-black mb-6 tracking-tighter uppercase italic">
              OPERATION <span className="text-brand-accent glitch-text" data-text="PROCEDURE">PROCEDURE</span>
            </h2>
            <p className="text-slate-500 font-mono uppercase tracking-[0.5em] text-xs">Tactical Enrollment Protocol // {Math.round(scrollProgress * 100)}% SYNCED</p>
          </div>

          <div className="relative flex flex-col items-center">

            {/* The Vertical Progress Line */}
            <div className="absolute left-1/2 -translate-x-1/2 top-0 bottom-0 w-1 md:w-2 bg-white/5 rounded-full overflow-hidden">
               {/* Glowing Fill */}
               <div 
                  className="absolute top-0 left-0 w-full bg-gradient-to-b from-brand-cyan via-brand-accent to-brand-secondary shadow-[0_0_20px_rgba(0,240,255,0.8)] transition-all duration-300 ease-out"
                  style={{ height: `${scrollProgress * 100}%` }}
               >
                 {/* Tip Glow Effect */}
                 <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-4 h-4 md:w-6 md:h-6 bg-white rounded-full blur-[4px] md:blur-[8px] animate-pulse"></div>
               </div>
            </div>

            {/* Step Content */}
            <div className="w-full space-y-48 relative">
              {(config.stepItems || []).map((step, idx) => {
                const Icon = stepIcons[idx] || Gamepad2;
                const threshold = (idx + 1) / (config.stepItems.length + 0.5);
                const isActive = scrollProgress >= threshold;
                const isEven = idx % 2 === 0;

                return (
                  <div 
                    key={idx} 
                    className={`flex flex-col md:flex-row items-center justify-between w-full transition-all duration-1000 ${isActive ? 'opacity-100 translate-y-0 scale-100' : 'opacity-10 translate-y-20 scale-95'}`}
                  >
                    {/* Content Column (Alternate Sides) */}
                    <div className={`w-full md:w-[45%] ${isEven ? 'order-2 md:order-1 text-center md:text-right' : 'order-2 text-center md:text-left'} mb-8 md:mb-0`}>
                       <div className={`inline-flex items-center gap-4 mb-4 ${isActive ? 'text-brand-cyan' : 'text-slate-700'}`}>
                         <span className="text-4xl md:text-6xl font-display font-black italic">0{idx + 1}</span>
                         <div className={`h-1 w-12 bg-current hidden md:block transition-all duration-1000 ${isActive ? 'w-24' : 'w-0'}`}></div>
                       </div>
                       <h3 className={`text-3xl md:text-5xl font-display font-black mb-4 uppercase tracking-tighter transition-colors duration-500 ${isActive ? 'text-white' : 'text-slate-800'}`}>
                         {step.title}
                       </h3>
                       <p className={`text-base md:text-xl font-light leading-relaxed max-w-md mx-auto md:mx-0 transition-colors duration-500 ${isActive ? 'text-slate-400' : 'text-slate-800'}`}>
                         {step.desc}
                       </p>
                    </div>

                    {/* Central Node (The Dot on the line) */}
                    <div className="order-1 md:order-2 relative z-20 mb-8 md:mb-0">
                       <div className={`w-16 h-16 md:w-24 md:h-24 rounded-full border-2 transition-all duration-700 flex items-center justify-center bg-black ${isActive ? 'border-brand-cyan shadow-[0_0_40px_rgba(0,240,255,0.4)] scale-110' : 'border-white/10 scale-90'}`}>
                          {isActive && <div className="absolute inset-0 rounded-full border-4 border-brand-cyan/20 animate-ping"></div>}
                          <Icon className={`w-8 h-8 md:w-12 md:h-12 transition-all duration-500 ${isActive ? 'text-brand-cyan' : 'text-slate-800'}`} />
                       </div>
                    </div>

                    {/* Visual Decor Column */}
                    <div className={`hidden md:block w-[45%] ${isEven ? 'order-3' : 'order-1'} transition-all duration-1000 ${isActive ? 'opacity-30 scale-100' : 'opacity-0 scale-75'}`}>
                        <div className="relative group">
                           <div className="absolute inset-0 bg-brand-cyan/20 blur-3xl rounded-full"></div>
                           <div className="border border-white/10 p-4 rounded-xl backdrop-blur-sm bg-black/40 rotate-3 group-hover:rotate-0 transition-transform">
                              <div className="w-full h-32 bg-slate-900/50 rounded flex items-center justify-center">
                                 <MousePointer2 className="w-12 h-12 text-slate-700 animate-bounce" />
                              </div>
                           </div>
                        </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </section>

      {/* Community Intel Marquee */}
      <section className="py-24 bg-black overflow-hidden border-y border-white/5 relative">
        <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-10"></div>
        <div className="text-center mb-16 relative z-10 animate-on-scroll">
          <h2 className="text-4xl md:text-7xl font-display font-black uppercase tracking-tighter">
            COMMUNITY <span className="text-brand-accent glitch-text" data-text="INTEL">INTEL</span>
          </h2>
          <p className="text-slate-500 font-mono mt-3 uppercase tracking-[0.4em] text-[10px] font-bold">Verified Agent Network Logs</p>
        </div>
        <div className="relative w-full hover:pause-marquee group animate-on-scroll">
          <div className="flex gap-10 w-max animate-marquee">
            {[...(config.reviews || []), ...(config.reviews || [])].map((review, i) => (
              <div key={i} onClick={() => review.type === 'video' ? setSelectedVideo(review) : null} className={`w-[340px] md:w-[420px] backdrop-blur-xl border border-white/10 rounded-2xl overflow-hidden transition-all duration-500 group/card ${review.type === 'video' ? 'cursor-pointer hover:border-brand-cyan/50 hover:shadow-[0_0_40px_rgba(0,240,255,0.15)]' : 'bg-white/5'} hover:-translate-y-4`}>
                {review.type === 'video' ? (
                  <>
                    <div className="relative h-56 w-full overflow-hidden">
                      <img src={review.thumbnail} alt="Intel Preview" className="w-full h-full object-cover opacity-60 group-hover/card:opacity-100 group-hover/card:scale-110 transition-all duration-1000" />
                      <div className="absolute inset-0 bg-black/50 flex items-center justify-center group-hover/card:bg-black/20 transition-colors">
                        <div className="w-20 h-20 rounded-full bg-white/10 backdrop-blur-xl border border-white/20 flex items-center justify-center pl-1.5 group-hover/card:bg-brand-accent group-hover/card:border-transparent transition-all shadow-2xl">
                          <Play className="w-8 h-8 text-white fill-white" />
                        </div>
                      </div>
                      <div className="absolute bottom-4 left-4 px-3 py-1 bg-brand-cyan/20 border border-brand-cyan/40 rounded text-[10px] font-black text-brand-cyan uppercase tracking-widest shadow-lg">VIDEO EVIDENCE</div>
                    </div>
                    <div className="p-8">
                      <div className="flex items-center gap-4 mb-6">
                        <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-brand-accent to-brand-secondary p-[1px] shadow-2xl">
                           <div className="w-full h-full bg-brand-dark rounded-xl flex items-center justify-center text-lg font-black text-white">{review.name.charAt(0)}</div>
                        </div>
                        <div>
                          <div className="font-black text-white font-display tracking-tight text-lg uppercase">{review.name}</div>
                          <div className="text-[10px] text-brand-cyan font-mono uppercase tracking-widest font-bold">{review.rank} AGENT</div>
                        </div>
                      </div>
                      <p className="text-slate-400 text-sm italic leading-relaxed font-medium">"{review.quote}"</p>
                    </div>
                  </>
                ) : (
                  <div className="p-8 flex flex-col h-full min-h-[300px] justify-between">
                    <div>
                      <div className="flex justify-between items-start mb-8">
                        <div className="flex items-center gap-4">
                           <div className="w-12 h-12 rounded-full bg-slate-800 border border-white/10 flex items-center justify-center text-lg font-black text-slate-300 shadow-inner">{review.name.charAt(0)}</div>
                           <div>
                              <div className="font-black text-white font-display tracking-tight uppercase text-lg">{review.name}</div>
                              <div className="text-[10px] text-slate-500 font-mono uppercase tracking-widest font-bold">{review.rank} CLASS</div>
                           </div>
                        </div>
                        <div className="flex gap-1 text-yellow-500 drop-shadow-[0_0_5px_rgba(234,179,8,0.5)]">
                          {Array.from({length: review.rating || 5}).map((_, i) => <Star key={i} size={14} fill="currentColor" />)}
                        </div>
                      </div>
                      <p className="text-slate-300 text-base leading-relaxed font-medium">"{review.quote}"</p>
                    </div>
                    <div className="flex items-center justify-between mt-auto pt-6">
                       <span className="text-[10px] font-mono text-slate-600 uppercase tracking-[0.4em] font-bold">{review.date || 'RECENT'}</span>
                       <div className="flex items-center gap-2 text-[10px] font-black text-green-400 bg-green-400/10 px-3 py-1 rounded-full border border-green-400/20 shadow-lg">
                          <CheckCircle2 size={12} /> SECURE RENT
                       </div>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </section>

      {selectedVideo && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 backdrop-blur-2xl animate-in fade-in duration-300 p-4">
          <div className="w-full max-w-6xl aspect-video rounded-none border border-brand-accent/50 relative bg-black shadow-[0_0_120px_rgba(255,70,85,0.25)]">
             <div className="absolute top-0 left-0 w-6 h-6 border-l-4 border-t-4 border-brand-accent"></div>
             <div className="absolute top-0 right-0 w-6 h-6 border-r-4 border-t-4 border-brand-accent"></div>
             <div className="absolute bottom-0 left-0 w-6 h-6 border-l-4 border-b-4 border-brand-accent"></div>
             <div className="absolute bottom-0 right-0 w-6 h-6 border-r-4 border-b-4 border-brand-accent"></div>
             <CustomVideoPlayer src={selectedVideo.videoUrl!} poster={selectedVideo.thumbnail} title={`INTEL DEBRIEF // ${selectedVideo.name}`} onClose={() => setSelectedVideo(null)} />
          </div>
        </div>
      )}

      {/* CTA Section */}
      <section className="py-32 bg-brand-darker relative overflow-hidden">
        <div className="absolute inset-0 bg-brand-accent/5"></div>
        <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-brand-accent to-transparent opacity-30"></div>
        <div className="max-w-5xl mx-auto text-center px-4 relative z-10">
          <div className="animate-on-scroll opacity-0 translate-y-10 scale-95 duration-1000 transform-gpu">
            <h2 className="text-6xl md:text-9xl font-display font-black mb-10 text-white uppercase tracking-tighter leading-[0.9]">
              {config.cta?.titleLine1} <br />
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-brand-accent to-brand-secondary glitch-text" data-text={config.cta?.titleLine2}>{config.cta?.titleLine2}</span>
            </h2>
            <p className="text-slate-400 mb-10 text-xl font-light tracking-wide max-w-2xl mx-auto">{config.cta?.subtitle}</p>
            <Link to="/browse" className="inline-block px-6 py-3 md:px-10 md:py-4 bg-white hover:bg-brand-cyan text-brand-darker font-black text-sm md:text-lg skew-x-[-12deg] transition-all hover:scale-105 shadow-[0_0_40px_rgba(255,255,255,0.3)] active:scale-95 uppercase tracking-widest">
              <div className="skew-x-[12deg]">{config.cta?.buttonText}</div>
            </Link>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;

import React, { useState, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { Shield, UserCog, Home, Gamepad2, User as UserIcon, LogOut, LayoutDashboard } from 'lucide-react';
import { StorageService } from '../services/storage';
import { User } from '../types';
import SkinSearchFloatingBar from './SkinSearchFloatingBar';

const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [showProfileMenu, setShowProfileMenu] = useState(false);

  const isHomePage = location.pathname === '/';

  // Listen for user changes
  useEffect(() => {
    setCurrentUser(StorageService.getCurrentUser());
  }, [location.pathname]);

  const handleLogout = () => {
    StorageService.logoutUser();
    setCurrentUser(null);
    setShowProfileMenu(false);
    navigate('/');
  };

  const isActive = (path: string) => location.pathname === path ? 'text-brand-accent drop-shadow-[0_0_8px_rgba(255,70,85,0.8)] border-b-2 border-brand-accent' : 'text-slate-400 hover:text-white hover:drop-shadow-[0_0_5px_rgba(255,255,255,0.5)]';

  const isTabActive = (path: string) => {
    if (path === '/') return location.pathname === '/';
    return location.pathname.startsWith(path);
  };

  return (
    <div className="min-h-screen bg-brand-darker text-slate-100 font-sans flex flex-col selection:bg-brand-accent selection:text-white relative">
      {/* CRT Scanline Effect Overlay */}
      <div className="scanlines"></div>

      {/* GLOBAL BRAND HEADER - Non-sticky, scrolls with the page */}
      <div className="w-full bg-black/80 border-b border-white/5 py-6 md:py-10 lg:py-12 flex justify-center items-center relative z-40 overflow-hidden">
        <div className="absolute inset-0 bg-brand-accent/5 pointer-events-none"></div>
        {/* Animated Background Shimmer for the Header */}
        <div className="absolute inset-y-0 left-0 w-1/3 bg-gradient-to-r from-transparent via-white/5 to-transparent -skew-x-12 animate-[marquee_5s_linear_infinite] opacity-30"></div>

        <div className="max-w-7xl w-full px-4 flex items-center justify-center relative">
          <Link to="/" className="flex items-center gap-4 md:gap-6 group relative z-10 transition-transform duration-300 hover:scale-105">
            <Shield className="h-8 w-8 md:h-12 md:w-12 text-brand-accent transition-all duration-500 group-hover:rotate-12 group-hover:drop-shadow-[0_0_20px_rgba(255,70,85,0.7)]" />
            <span className="font-display font-black text-2xl md:text-5xl lg:text-6xl tracking-tighter text-white whitespace-nowrap uppercase italic">
              KRISHNA <span className="text-brand-accent">VALO</span> STORE
            </span>
          </Link>

          {/* Visual Docking Spot for Search Bar on Right */}
          <div className="absolute right-0 top-1/2 -translate-y-1/2 flex items-center gap-4">
             {/* This empty space is reserved for the animated SkinSearchFloatingBar */}
             <div className="w-12 h-12"></div>
          </div>
        </div>
      </div>

      {/* Navbar - Sticky Navigation (Desktop classical menu hidden or simplified if using Bottom Dock) */}
      {isHomePage && (
        <nav className="hidden md:block sticky top-0 w-full z-30 bg-brand-dark/80 backdrop-blur-xl border-b border-white/10 shadow-[0_4px_30px_rgba(0,0,0,0.3)]">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
