import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Search, X, ArrowRight } from 'lucide-react';

interface SkinSearchFloatingBarProps {
  isHomePage: boolean;
}

const SkinSearchFloatingBar: React.FC<SkinSearchFloatingBarProps> = ({ isHomePage }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const [query, setQuery] = useState('');
  const [isFocused, setIsFocused] = useState(false);
  const [arrivalPulse, setArrivalPulse] = useState(false);
  const prevIsHome = useRef(isHomePage);

  // Trigger a pulse effect when the bar finishes docking into the header
  useEffect(() => {
    if (prevIsHome.current && !isHomePage) {
      setArrivalPulse(true);
      const timer = setTimeout(() => setArrivalPulse(false), 1000);
      return () => clearTimeout(timer);
    }
    prevIsHome.current = isHomePage;
  }, [isHomePage]);

  // Sync with URL query param if present
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const q = params.get('q');
    if (q) setQuery(q);
  }, [location.search]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      navigate(`/browse?q=${encodeURIComponent(query.trim())}`);
      setIsFocused(false);
      const activeElement = document.activeElement as HTMLElement;
      if (activeElement) activeElement.blur();
    }
  };

  const handleClear = () => {
      setQuery('');
      navigate('/browse');
  };

  const mode = isHomePage ? 'hero' : 'header';

  return (
    <>
        {/* Backdrop - Only when focused */}
        <div 
            className={`fixed inset-0 bg-black/60 backdrop-blur-[6px] z-[55] transition-all duration-700 ${isFocused ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
            onClick={() => setIsFocused(false)}
        />

        {/* 
            Floating Bar Container 
            - Uses 'absolute' on Home Page so it scrolls with the page content.
            - Uses 'fixed' on other pages to dock into the header.
            - Transitions between absolute and fixed are handled smoothly by CSS.
        */}
        <div 
            className={`${(isHomePage && !isFocused) ? 'absolute' : 'fixed'} z-[60] transition-all duration-[850ms] ease-[cubic-bezier(0.34,1.56,0.64,1)] 
                ${isFocused 
                    ? 'top-32 md:top-40 left-1/2 -translate-x-1/2 w-[calc(100%-2.5rem)] md:w-[600px] scale-100' 
                    : mode === 'hero'
                        ? 'top-52 md:top-64 left-1/2 -translate-x-1/2 w-fit scale-100'
                        : 'top-5 right-3 md:right-10 md:top-6 w-fit translate-x-0 scale-90 md:scale-100'
                }
            `}
        >
            {/* Arrival Pulse Glow (Header Mode Only) */}
            {arrivalPulse && !isHomePage && (
              <div className="absolute inset-0 bg-brand-cyan/40 rounded-full animate-ping pointer-events-none"></div>
            )}

            <div className={`transition-all duration-500 ${!isFocused && mode === 'hero' ? 'animate-float' : ''}`}>
                {/* Visual Glow Layer */}
                <div className={`absolute inset-0 rounded-full blur-2xl transition-all duration-700 
                  ${isFocused 
                    ? 'bg-brand-cyan/20 opacity-100 scale-110' 
                    : mode === 'hero' 
                      ? 'bg-brand-accent/20 opacity-60 scale-90' 
                      : 'bg-brand-cyan/0 opacity-0'
                  }`} 
                />

                <form 
                    onSubmit={handleSearch}
                    onClick={() => !isFocused && setIsFocused(true)}
                    className={`relative flex items-center bg-brand-darker/80 backdrop-blur-2xl border rounded-full shadow-[0_15px_50px_rgba(0,0,0,0.6)] overflow-hidden transition-all duration-[850ms] ease-[cubic-bezier(0.34,1.56,0.64,1)] cursor-text group
                        ${isFocused 
                            ? 'w-full ring-2 ring-brand-cyan/40 py-5 px-7 border-brand-cyan/40' 
                            : mode === 'hero'
                                ? 'w-[64px] md:w-[320px] py-4 px-4 md:px-6 border-white/10 hover:border-brand-accent/40 hover:shadow-[0_0_25px_rgba(255,70,85,0.3)]'
                                : 'w-[44px] h-[44px] md:w-[48px] md:h-[48px] py-0 px-0 justify-center hover:bg-white/10 border-white/5 bg-black/40'
                        }
                    `}
                >
                    {/* Cyber Grid Pattern Background (Visible when focused) */}
                    <div className={`absolute inset-0 opacity-10 pointer-events-none transition-opacity duration-700 ${isFocused ? 'opacity-20' : 'opacity-0'}`} 
                         style={{ backgroundImage: 'radial-gradient(circle at 1px 1px, #00f0ff 1px, transparent 0)', backgroundSize: '16px 16px' }} />

                    {/* Search Icon with dynamic rotation */}
                    <div className={`flex items-center justify-center transition-all duration-[850ms] ${isFocused ? 'mr-5 scale-110 rotate-90' : (mode === 'hero' ? 'mr-0 md:mr-3 rotate-0' : 'mr-0 rotate-0')}`}>
                         <div className={`transition-all duration-500 p-2 rounded-full ${isFocused ? 'bg-brand-cyan/20 text-brand-cyan' : 'bg-transparent text-slate-400 group-hover:text-white'}`}>
                             <Search className={`${mode === 'header' && !isFocused ? 'w-5 h-5 md:w-6 h-6' : 'w-5 h-5 md:w-6 md:h-6'}`} strokeWidth={2.5} />
                         </div>
                    </div>

                    {/* Input Field */}
                    <input 
                        name="skin-search"
                        type="text" 
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        onFocus={() => setIsFocused(true)}
                        placeholder="Search Skins..."
                        autoComplete="off"
                        className={`bg-transparent border-none outline-none text-white placeholder-slate-500 font-display font-bold text-lg tracking-wide transition-all duration-[850ms]
                            ${isFocused 
                                ? 'flex-1 opacity-100' 
                                : mode === 'hero'
                                    ? 'hidden md:block w-full opacity-100 md:w-48 cursor-text'
                                    : 'hidden'
                            }
                        `}
                    />

                    {/* Actions / Submit */}
                    <div className={`flex items-center gap-3 transition-all duration-500 ${isFocused || (mode === 'hero' && query) ? 'opacity-100 translate-x-0' : 'opacity-0 translate-x-10 w-0'}`}>
                        {query && isFocused && (
                            <button 
                                type="button"
                                onClick={(e) => { e.stopPropagation(); handleClear(); }}
                                className="p-2 hover:bg-white/10 rounded-full text-slate-500 hover:text-white transition-all hover:scale-110"
                            >
                                <X className="w-5 h-5" />
