          {/* Animated Slide Indicator */}
          <div className="mt-16 md:mt-24 flex items-center justify-center gap-4 animate-reveal-up" style={{ animationDelay: '0.7s' }}>
            {(config.heroSlides || []).map((slide, idx) => (
              <button
