    imageUrl: 'https://images.unsplash.com/photo-1542751371-adc38448a05e?q=80&w=1000&auto=format&fit=crop',
    username: '',
    password: '',
    description: 'Premium Valorant Account with verified skins.',
    initialSkinsCount: 10
