/**
 * Dispatches a custom event to notify components in the same tab about storage changes.
 * Using a custom name 'valo-storage-update' avoids 'Illegal constructor' errors that
 * occur when trying to manually construct the native 'storage' event in some browsers.
 */
const notifyStorageChange = () => {
  let event;
  const eventName = 'valo-storage-update';

  if (typeof CustomEvent === 'function') {
    event = new CustomEvent(eventName);
  } else {
    event = document.createEvent('CustomEvent');
    (event as any).initCustomEvent(eventName, true, true, {});
  }
  window.dispatchEvent(event);
};

