        console.error("Failed to load admin data:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated) {
      refreshData();
      const interval = setInterval(refreshData, 30000);
      window.addEventListener('valo-storage-update', refreshData);
      window.addEventListener('storage', refreshData);
      return () => {
        clearInterval(interval);
        window.removeEventListener('valo-storage-update', refreshData);
        window.removeEventListener('storage', refreshData);
      };
    }
  }, [isAuthenticated]);

  const stats = useMemo(() => ({
    totalBookings: bookings.length,
    monthlyRevenue: bookings.filter(b => (b.status === BookingStatus.ACTIVE || b.status === BookingStatus.COMPLETED)).reduce((sum, b) => sum + b.totalPrice, 0),
