// Internal listener system to avoid "Illegal constructor" with native Event/CustomEvent
type StorageListener = () => void;
const listeners = new Set<StorageListener>();

const notifyStorageChange = () => {
  // Notify internal listeners (same tab)
  listeners.forEach(listener => {
    try {
      listener();
    } catch (e) {
      console.error("Listener error:", e);
    }
  });

  // Cross-tab notification via native storage event if available
  try {
    localStorage.setItem('valo_storage_sync', Date.now().toString());
  } catch (e) {
