  useEffect(() => {
    const loadAccount = async () => {
      try {
        if (id) {
          const acc = await StorageService.getAccountById(id);
          setAccount(acc);
        }
      } finally {
        setLoading(false);
      }
    };
    loadAccount();
    window.scrollTo(0, 0);
  }, [id]);

  useEffect(() => {
    if (!account || !account.isBooked || !account.bookedUntil) {
      setIsEffectivelyAvailable(true);
