const RentalCard: React.FC<{ booking: Booking, showCredentials?: boolean }> = ({ booking, showCredentials }) => {
  const [timeLeft, setTimeLeft] = useState<string>('--:--:--');
  const [isRevealed, setIsRevealed] = useState(false);
  const [account, setAccount] = useState<Account | undefined>(undefined);

  useEffect(() => {
    if (showCredentials) StorageService.getAccountById(booking.accountId).then(setAccount);
  }, [booking.accountId, showCredentials]);

  useEffect(() => {
    if (booking.status !== BookingStatus.ACTIVE) return;
    const interval = setInterval(() => {
      const distance = new Date(booking.endTime).getTime() - Date.now();
      if (distance < 0) {
        setTimeLeft("EXPIRED");
        clearInterval(interval);
      } else {
        const h = Math.floor(distance / (1000 * 60 * 60));
        const m = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
        const s = Math.floor((distance % (1000 * 60)) / 1000);
        setTimeLeft(`${h}h ${m}m ${s}s`);
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [booking]);

  return (
    <div className="bg-brand-surface border border-white/10 rounded-2xl overflow-hidden p-8 relative">
       <div className="flex flex-col sm:flex-row justify-between items-start gap-4 mb-8">
          <div>
             <h3 className="text-2xl font-display font-black text-white uppercase italic tracking-tighter mb-1">{booking.accountName}</h3>
             <div className="flex items-center gap-2 text-[10px] text-slate-500 font-black uppercase tracking-widest">
                <span className="bg-white/10 px-2 py-0.5 rounded">{booking.orderId}</span>
                <span>•</span>
                <span className="text-brand-cyan">{booking.durationLabel} SESSION</span>
             </div>
          </div>
          <div className="text-left sm:text-right w-full sm:w-auto">
             {booking.status === BookingStatus.ACTIVE ? (
               <div className="text-3xl font-mono font-black text-brand-cyan drop-shadow-[0_0_10px_#00f0ff]">{timeLeft}</div>
             ) : (
               <span className="px-4 py-2 bg-yellow-500/10 text-yellow-500 border border-yellow-500/20 rounded-xl text-[10px] font-black uppercase tracking-widest">{booking.status}</span>
             )}
          </div>
       </div>

       {showCredentials && booking.status === BookingStatus.ACTIVE && account && (
         <div className="bg-brand-dark p-6 rounded-2xl border border-white/5 relative overflow-hidden">
            {!isRevealed ? (
               <div className="absolute inset-0 bg-black/80 backdrop-blur-md flex flex-col items-center justify-center z-20">
                  <ShieldCheck className="text-brand-accent mb-3" size={32} />
                  <button onClick={() => setIsRevealed(true)} className="px-8 py-3 bg-white text-brand-darker font-black text-[10px] rounded-xl uppercase tracking-widest shadow-2xl hover:bg-brand-cyan transition-colors">Reveal Credentials</button>
               </div>
            ) : <button onClick={() => setIsRevealed(false)} className="absolute top-4 right-4 text-slate-500 hover:text-white z-30 transition-colors"><EyeOff size={18}/></button>}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div>
                  <label className="text-[10px] font-black uppercase text-slate-500 mb-2 block tracking-widest">Target Username</label>
                  <div className="bg-black/50 p-4 rounded-xl border border-white/5 font-mono text-brand-cyan flex justify-between group">
                     {account.username}
                     <button onClick={() => { navigator.clipboard.writeText(account.username || ''); alert("Copied!"); }} className="opacity-0 group-hover:opacity-100 transition-opacity"><Copy size={14} /></button>
                  </div>
               </div>
               <div>
                  <label className="text-[10px] font-black uppercase text-slate-500 mb-2 block tracking-widest">Encryption Key</label>
                  <div className="bg-black/50 p-4 rounded-xl border border-white/5 font-mono text-brand-cyan flex justify-between group">
                     {account.password}
                     <button onClick={() => { navigator.clipboard.writeText(account.password || ''); alert("Copied!"); }} className="opacity-0 group-hover:opacity-100 transition-opacity"><Copy size={14} /></button>
                  </div>
               </div>
            </div>
         </div>
       )}

       {booking.status === BookingStatus.PENDING && (
         <div className="mt-4 p-4 bg-brand-cyan/10 border border-brand-cyan/20 rounded-2xl flex items-center gap-4">
            <Loader2 className="text-brand-cyan animate-spin" size={20} />
            <p className="text-xs text-brand-cyan font-bold uppercase tracking-widest">Awaiting admin authorization...</p>
         </div>
       )}
    </div>
  );
};

