const RentalCard: React.FC<{ booking: Booking, showCredentials?: boolean }> = ({ booking, showCredentials }) => {
  const [timeLeft, setTimeLeft] = useState<string>('--:--:--');
  const [isRevealed, setIsRevealed] = useState(false);
  const [account, setAccount] = useState<Account | undefined>(undefined);

  useEffect(() => {
    if (showCredentials) StorageService.getAccountById(booking.accountId).then(setAccount);
  }, [booking.accountId, showCredentials]);

  useEffect(() => {
    if (booking.status !== BookingStatus.ACTIVE) return;
    const interval = setInterval(() => {
      const distance = new Date(booking.endTime).getTime() - Date.now();
      if (distance < 0) {
        setTimeLeft("EXPIRED");
        clearInterval(interval);
      } else {
        const h = Math.floor(distance / (1000 * 60 * 60));
        const m = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
        const s = Math.floor((distance % (1000 * 60)) / 1000);
        setTimeLeft(`${h}h ${m}m ${s}s`);
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [booking]);

  return (
    <div className="bg-brand-surface border border-white/10 rounded-2xl overflow-hidden p-8 relative group">
      <div className="flex flex-col sm:flex-row justify-between items-start gap-4 mb-4">
         <div>
           <h3 className="font-bold text-xl text-white mb-1 uppercase tracking-tight">{booking.accountName}</h3>
           <div className="flex items-center gap-2 text-[10px] text-slate-500 font-black uppercase tracking-widest">
             <span className="bg-white/10 px-2 py-0.5 rounded">{booking.orderId}</span>
             <span>•</span>
             <span>{booking.durationLabel}</span>
           </div>
         </div>
         <div className="text-right">
            {booking.status === BookingStatus.ACTIVE ? (
               <div className="text-xl font-mono font-bold text-brand-cyan">{timeLeft}</div>
            ) : (
              <span className="px-3 py-1 bg-yellow-500/10 text-yellow-500 border border-yellow-500/20 rounded-full text-[10px] font-black uppercase">{booking.status}</span>
            )}
         </div>
      </div>
      {showCredentials && booking.status === BookingStatus.ACTIVE && account && (
        <div className="mt-6 bg-brand-dark p-4 rounded-lg border border-white/5 relative overflow-hidden">
           {!isRevealed ? (
             <div className="absolute inset-0 bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center z-10">
                <ShieldCheck className="text-brand-accent mb-2" />
                <button onClick={() => setIsRevealed(true)} className="px-4 py-2 bg-white text-black font-black text-[10px] uppercase rounded">Reveal Credentials</button>
             </div>
           ) : <button onClick={() => setIsRevealed(false)} className="absolute top-2 right-2 text-slate-500 hover:text-white z-20"><EyeOff size={14}/></button>}
           <div className="grid grid-cols-2 gap-4">
              <div><label className="text-[9px] uppercase text-slate-500 font-black mb-1 block">Username</label><code className="text-xs text-brand-cyan font-mono">{account.username}</code></div>
              <div><label className="text-[9px] uppercase text-slate-500 font-black mb-1 block">Password</label><code className="text-xs text-brand-cyan font-mono">{account.password}</code></div>
           </div>
        </div>
      )}
    </div>
  );
};

