              ))}
              {account.skins.length > 4 && (
                 <span className="text-[10px] px-2 py-1 bg-white/5 text-slate-500 border border-white/10 block font-mono">
                   +{account.skins.length - 4}
                 </span>
              )}
            </div>
          </div>

          {/* Pricing Grid */}
          <div className="grid grid-cols-4 gap-2 mb-5">
