export const StorageService = {
  subscribe: (callback: StorageListener) => {
    listeners.add(callback);
    return () => listeners.delete(callback);
  },

  // --- Messages ---
  sendMessage: async (message: Message) => {
    // Assuming a 'messages' table exists in Supabase with a 'data' jsonb column similar to other tables
    await getSupabase().from('messages').insert({ id: message.id, data: message });
    notifyStorageChange();
  },

  getMessages: async (userId1: string, userId2: string, accountId: string): Promise<Message[]> => {
    const { data, error } = await getSupabase().from('messages').select('data');
    if (error || !data) return [];

    const allMessages = data.map(row => row.data as Message);

    // Filter messages between these two users related to specific account
    // Order by createdAt ASC
    return allMessages
      .filter(m => 
        m.accountId === accountId && 
        ((m.senderId === userId1 && m.receiverId === userId2) || 
         (m.senderId === userId2 && m.receiverId === userId1))
      )
      .sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
  },

  getAllUserMessages: async (userId: string): Promise<Message[]> => {
    // Fetch all messages where user is sender or receiver
    const { data, error } = await getSupabase().from('messages').select('data');
    if (error || !data) return [];

    return data
      .map(row => row.data as Message)
      .filter(m => m.senderId === userId || m.receiverId === userId)
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  },

  markMessagesAsRead: async (senderId: string, receiverId: string, accountId: string) => {
    // In a real DB, we would do an UPDATE query. Here we have to fetch, update, and save back if simulating with JSONB
    // Since this uses Supabase 'data' column, we can't easily do a bulk update on JSON fields without PG logic.
    // For this implementation, we will assume the client handles 'read' state optimistically or 
    // we fetch relevant messages and update them one by one.

    const { data } = await getSupabase().from('messages').select('*');
    if (!data) return;

    const updates = data
      .map(row => ({ id: row.id, data: row.data as Message }))
      .filter(item => 
        item.data.senderId === senderId && 
        item.data.receiverId === receiverId && 
        item.data.accountId === accountId &&
        !item.data.isRead
      );

    for (const item of updates) {
      item.data.isRead = true;
      await getSupabase().from('messages').update({ data: item.data }).eq('id', item.id);
    }
    notifyStorageChange();
  },

  validateCoupon: async (code: string): Promise<{ valid: boolean; type?: 'PERCENT' | 'FLAT'; value?: number; message: string }> => {
    const normalized = code.toUpperCase().trim();

    // Fetch latest config to get dynamic coupons
    const config = await StorageService.getHomeConfig();
    const coupons = config.coupons || DEFAULT_HOME_CONFIG.coupons || [];

    // Simulate Network Delay for realism
    await new Promise(resolve => setTimeout(resolve, 600));

    const matched = coupons.find(c => c.code === normalized && c.active);

    if (!matched) {
       return { valid: false, message: 'Invalid or expired coupon code.' };
    }

    // Check Expiration
    if (matched.expiryDate) {
      const now = new Date();
      const expiry = new Date(matched.expiryDate);
      // Set expiry to end of that day
      expiry.setHours(23, 59, 59, 999);

      if (now > expiry) {
        return { valid: false, message: 'This coupon has expired.' };
      }
    }

    // Check Usage Limit
    if (matched.maxUses !== null && matched.maxUses !== undefined) {
      if (matched.currentUses >= matched.maxUses) {
        return { valid: false, message: 'Coupon usage limit reached.' };
      }
    }

    return { valid: true, type: matched.type, value: matched.value, message: 'Coupon applied successfully!' };
  },

  incrementCouponUsage: async (code: string) => {
    try {
      const config = await StorageService.getHomeConfig();
      if (!config.coupons) return;

      const updatedCoupons = config.coupons.map(c => {
          if (c.code === code) {
              return { ...c, currentUses: (c.currentUses || 0) + 1 };
          }
          return c;
      });

      await StorageService.saveHomeConfig({ ...config, coupons: updatedCoupons });
    } catch (e) {
      console.error("Failed to increment coupon usage:", e);
    }
  },

  getAccounts: async (rankFilter?: string): Promise<Account[]> => {
    let query = getSupabase().from('accounts').select('*');

    // Server-side filtering for Rank using JSONB syntax
    if (rankFilter && rankFilter !== 'All') {
       query = query.eq('data->>rank', rankFilter);
    }

    const { data, error } = await query;
    if (error || !data) return [];
    return data.map(row => row.data as Account);
  },

  getUserListings: async (userId: string): Promise<Account[]> => {
    const { data, error } = await getSupabase().from('accounts').select('*').eq('data->>listedBy', userId);
    if (error || !data) return [];
    return data.map(row => row.data as Account);
  },

  getAccountById: async (id: string): Promise<Account | undefined> => {
    const { data, error } = await getSupabase().from('accounts').select('data').eq('id', id).single();
    if (error || !data) return undefined;
    return data.data as Account;
  },

  saveAccount: async (account: Account) => {
    await getSupabase().from('accounts').upsert({ id: account.id, data: account });
    notifyStorageChange();
  },

  updateAccountPassword: async (accountId: string, newPassword: string) => {
    const account = await StorageService.getAccountById(accountId);
    if (account) {
      account.password = newPassword;
      await StorageService.saveAccount(account);
    }
  },

  deleteAccount: async (id: string) => {
    await getSupabase().from('accounts').delete().eq('id', id);
    notifyStorageChange();
  },

  getBookings: async (accountId?: string): Promise<Booking[]> => {
    let query = getSupabase().from('bookings').select('*').order('data->createdAt', { ascending: false });
    const { data, error } = await query;
    if (error || !data) return [];

    let bookings = data.map(row => row.data as Booking);
    if (accountId) {
      bookings = bookings.filter(b => b.accountId === accountId);
    }
    return bookings;
  },

  getUserBookings: async (userId: string): Promise<Booking[]> => {
    const bookings = await StorageService.getBookings();
    return bookings.filter(b => b.customerId === userId);
  },

  // Check if a time slot is available for an account
  checkAvailability: async (accountId: string, startTime: string, endTime: string): Promise<boolean> => {
    const bookings = await StorageService.getBookings(accountId);

    const newStart = new Date(startTime).getTime();
    const newEnd = new Date(endTime).getTime();

    const conflicts = bookings.filter(b => {
      // Ignore Cancelled, Completed, AND PENDING (Requested but not approved/locked yet)
      if (b.status === BookingStatus.CANCELLED || 
          b.status === BookingStatus.COMPLETED || 
          b.status === BookingStatus.PENDING) return false;

      const bStart = new Date(b.startTime).getTime();
      const bEnd = new Date(b.endTime).getTime();

      // Check overlap: (StartA < EndB) and (EndA > StartB)
      return (newStart < bEnd && newEnd > bStart);
    });

    return conflicts.length === 0;
  },

  createBooking: async (booking: Booking) => {
    await getSupabase().from('bookings').upsert({ order_id: booking.orderId, data: booking, status: booking.status });
    notifyStorageChange();
  },

  updateBooking: async (booking: Booking) => {
    await getSupabase().from('bookings').update({ data: booking, status: booking.status }).eq('order_id', booking.orderId);
    notifyStorageChange();
  },

  deleteBooking: async (orderId: string) => {
    await getSupabase().from('bookings').delete().eq('order_id', orderId);
    notifyStorageChange();
  },

  updateBookingStatus: async (orderId: string, status: BookingStatus) => {
    const { data: row } = await getSupabase().from('bookings').select('data').eq('order_id', orderId).single();

    if (row?.data) {
      const booking = row.data as Booking;

      // Safety Check: If trying to approve (ACTIVE/PRE_BOOKED), ensure slot is still free from *other* active bookings
      if (status === BookingStatus.ACTIVE || status === BookingStatus.PRE_BOOKED) {
         // checkAvailability ignores PENDING, so it won't flag this booking itself as a conflict.
         // It will only flag if there is already an ACTIVE/PRE_BOOKED session overlapping.
         const isAvailable = await StorageService.checkAvailability(booking.accountId, booking.startTime, booking.endTime);
         if (!isAvailable) {
             throw new Error("Conflict detected: This slot has already been approved for another user.");
         }
      }

      const oldStatus = booking.status;
      if (oldStatus === status) return;

      booking.status = status;

      await getSupabase().from('bookings').update({ data: booking, status: status }).eq('order_id', orderId);

      // Points Logic
      if (booking.customerId) {
        const points = Math.floor(booking.totalPrice / 9);

        // Mark as active/pre-booked (Approved) -> Add points
        if (oldStatus === BookingStatus.PENDING && (status === BookingStatus.ACTIVE || status === BookingStatus.PRE_BOOKED)) {
          await StorageService.updateUserPoints(booking.customerId, points);
        } 
        // Cancelled -> Deduct points
        else if ((oldStatus === BookingStatus.ACTIVE || oldStatus === BookingStatus.PRE_BOOKED) && status === BookingStatus.CANCELLED) {
          await StorageService.updateUserPoints(booking.customerId, -points);
        }
      }

      const account = await StorageService.getAccountById(booking.accountId);

      if (account) {
        // Logic for account status updates
        // If a booking transitions to ACTIVE, we lock the account
        if (status === BookingStatus.ACTIVE) {
          account.isBooked = true;
          account.bookedUntil = booking.endTime;
        } 
        // If a booking is Cancelled or Completed, we only unlock if THIS booking was the one locking it
        else if (status === BookingStatus.COMPLETED || status === BookingStatus.CANCELLED) {
          if (account.isBooked && account.bookedUntil === booking.endTime) {
            account.isBooked = false;
            account.bookedUntil = null;
          }
        }
        await StorageService.saveAccount(account);
      }

      notifyStorageChange();
    }
  },

  // Automatically check for expired bookings and pending locks
  checkExpiredBookings: async () => {
    try {
      const bookings = await StorageService.getBookings();
      const now = new Date().getTime();
      let hasUpdates = false;

      for (const booking of bookings) {
        const endTime = new Date(booking.endTime).getTime();
        const startTime = new Date(booking.startTime).getTime();
        const createdAt = new Date(booking.createdAt).getTime();

        // 1. Expire Active Bookings
        if (booking.status === BookingStatus.ACTIVE && endTime <= now) {
          await StorageService.updateBookingStatus(booking.orderId, BookingStatus.COMPLETED);
          hasUpdates = true;
        }

        // 2. Activate Pre-Bookings when time arrives
        if (booking.status === BookingStatus.PRE_BOOKED && startTime <= now && endTime > now) {
          await StorageService.updateBookingStatus(booking.orderId, BookingStatus.ACTIVE);
          hasUpdates = true;
        }

        // 3. Cleanup Pending Locks (> 10 mins old)
        if (booking.status === BookingStatus.PENDING) {
           const tenMins = 10 * 60 * 1000;
           if (now - createdAt > tenMins) {
             // Silently delete or cancel expired pending requests to free up the slot
             await StorageService.deleteBooking(booking.orderId);
             hasUpdates = true;
           }
        }
      }

      if (hasUpdates) {
        notifyStorageChange();
      }
    } catch (e) {
      console.error("Error checking expired bookings:", e);
    }
  },

  updateUserPoints: async (userId: string, amount: number) => {
    const { data: row } = await getSupabase().from('users').select('data').eq('id', userId).single();
    if (row?.data) {
      const userData = row.data as User;
      userData.ultraPoints = (userData.ultraPoints || 0) + amount;

      await getSupabase().from('users').update({ data: userData }).eq('id', userId);

      const currentUser = StorageService.getCurrentUser();
      if (currentUser && currentUser.id === userId) {
        localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(userData));
      }
      notifyStorageChange();
    }
  },

  getHomeConfig: async (): Promise<HomeConfig> => {
    try {
      const { data, error } = await getSupabase().from('home_config').select('data').eq('id', 'global').single();
      if (error || !data?.data) return DEFAULT_HOME_CONFIG;

      const config = data.data as HomeConfig;
      return {
        ...DEFAULT_HOME_CONFIG,
        ...config,
        trustItems: config.trustItems && config.trustItems.length > 0 ? config.trustItems : DEFAULT_HOME_CONFIG.trustItems,
        heroSlides: config.heroSlides && config.heroSlides.length > 0 ? config.heroSlides : DEFAULT_HOME_CONFIG.heroSlides,
        marqueeText: config.marqueeText && config.marqueeText.length > 0 ? config.marqueeText : DEFAULT_HOME_CONFIG.marqueeText,
        stepItems: config.stepItems && config.stepItems.length > 0 ? config.stepItems : DEFAULT_HOME_CONFIG.stepItems,
        reviews: config.reviews && config.reviews.length > 0 ? config.reviews : DEFAULT_HOME_CONFIG.reviews,
        ultraPoints: config.ultraPoints || DEFAULT_HOME_CONFIG.ultraPoints,
        coupons: config.coupons || DEFAULT_HOME_CONFIG.coupons,
        cta: config.cta || DEFAULT_HOME_CONFIG.cta
      };
    } catch {
      return DEFAULT_HOME_CONFIG;
    }
  },

  saveHomeConfig: async (config: HomeConfig) => {
    const { error } = await getSupabase().from('home_config').upsert({ id: 'global', data: config });
    if (error) throw error;
    notifyStorageChange();
  },

  getCurrentUser: (): User | null => {
    const data = localStorage.getItem(CURRENT_USER_KEY);
    return data ? JSON.parse(data) : null;
  },

  logoutUser: () => {
    localStorage.removeItem(CURRENT_USER_KEY);
    notifyStorageChange();
  },

  getAllUsers: async (): Promise<User[]> => {
    const { data, error } = await getSupabase().from('users').select('data');
    if (error || !data) return [];
    return data.map(row => row.data as User);
  },

  deleteUser: async (userId: string) => {
    await getSupabase().from('users').delete().eq('id', userId);
    notifyStorageChange();
  },

  registerUser: async (name: string, email: string, phone: string, password: string): Promise<User> => {
    const newUser: User = {
      id: 'usr-' + Date.now(),
      name, email, phone, password,
      avatarUrl: `https://api.dicebear.com/7.x/avataaars/svg?seed=${name}`,
      role: 'customer',
      isVerified: true,
      ultraPoints: 20, // Welcome Bonus
      createdAt: new Date().toISOString(),
      lastLogin: new Date().toISOString()
    };
    await getSupabase().from('users').insert({ id: newUser.id, email: newUser.email, data: newUser });
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(newUser));
    notifyStorageChange();
    return newUser;
  },

  loginUser: async (email: string, password: string): Promise<User> => {
    const { data, error } = await getSupabase().from('users').select('data').eq('email', email).single();
    if (error || !data) throw new Error("Invalid credentials");
    const user = data.data as User;
    if (user.password !== password) throw new Error("Invalid credentials");

    user.lastLogin = new Date().toISOString();
    await getSupabase().from('users').update({ data: user }).eq('id', user.id);

    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
    notifyStorageChange();
    return user;
  }
};

import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate, Navigate } from 'react-router-dom';
import { Account, UPI_ID, BookingStatus, Booking } from '../types';
import { StorageService } from '../services/storage';
import { Copy, ArrowRight, Timer, CalendarClock, Smartphone, ShieldCheck, Zap, Send, Ticket, CheckCircle, XCircle, Loader2, AlertCircle, MessageCircle } from 'lucide-react';

interface CheckoutState {
  orderId?: string; // Optional because legacy flow might not have it, but new flow will
  account: Account;
  hours: number;
  price: number;
  originalPrice?: number;
  durationLabel: '1 Hour' | '3 Hours' | '12 Hours' | '24 Hours';
  startMode: 'now' | 'later';
  scheduledTime?: string;
}

const Checkout: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const state = location.state as CheckoutState;

  const [orderId, setOrderId] = useState(state?.orderId || '');
  const [timer, setTimer] = useState(600); // 10 minutes for payment
  const [utr, setUtr] = useState('');
  const [error, setError] = useState('');

  // Coupon State
  const [couponCode, setCouponCode] = useState('');
  const [appliedCoupon, setAppliedCoupon] = useState<{ code: string; type: 'PERCENT' | 'FLAT'; value: number } | null>(null);
  const [couponMessage, setCouponMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [isValidatingCoupon, setIsValidatingCoupon] = useState(false);

  const currentUser = StorageService.getCurrentUser();

  useEffect(() => {
    if (state && !state.orderId) {
      // Fallback generation if no pre-locked ID (Legacy support)
      const id = 'KV-' + Math.floor(1000 + Math.random() * 9000);
      setOrderId(id);
    }
  }, [state]);

  // Payment Timer countdown
  useEffect(() => {
    if (timer > 0) {
      const interval = setInterval(() => setTimer(t => t - 1), 1000);
      return () => clearInterval(interval);
    } else {
       // Timer expired - navigate away or show error
       setError("Session expired.");
    }
  }, [timer]);

  if (!state) {
    return <Navigate to="/browse" />;
  }

  // Calculate rental period for display
  const startDateTime = state.startMode === 'later' && state.scheduledTime 
    ? new Date(state.scheduledTime) 
    : new Date();

  const endDateTime = new Date(startDateTime.getTime() + state.hours * 60 * 60 * 1000);

  const formatTimer = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  // --- Price Calculations ---
  const basePrice = state.price;
  let finalPrice = basePrice;
  let discountAmount = 0;

  if (appliedCoupon) {
    if (appliedCoupon.type === 'PERCENT') {
      discountAmount = Math.floor((basePrice * appliedCoupon.value) / 100);
    } else {
      discountAmount = appliedCoupon.value;
    }
    // Prevent negative price
    if (discountAmount > basePrice) discountAmount = basePrice;
    finalPrice = basePrice - discountAmount;
  }

  // Construct UPI URI with amount and order ID
  // tn (Transaction Note) is critical here - it puts the Order ID in the bank statement for the admin
  const upiString = `upi://pay?pa=${UPI_ID}&pn=KrishnaValo&am=${finalPrice.toFixed(2)}&cu=INR&tn=${orderId}`;
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=250x250&margin=10&data=${encodeURIComponent(upiString)}`;

  // --- Coupon Handlers ---
  const handleApplyCoupon = async () => {
    if (!couponCode.trim()) return;
    setIsValidatingCoupon(true);
    setCouponMessage(null);
    setAppliedCoupon(null);

    try {
      const result = await StorageService.validateCoupon(couponCode);
      if (result.valid && result.type && result.value) {
         setAppliedCoupon({ code: couponCode.toUpperCase(), type: result.type, value: result.value });
         setCouponMessage({ type: 'success', text: result.message });
      } else {
         setCouponMessage({ type: 'error', text: result.message });
      }
    } catch (err) {
      setCouponMessage({ type: 'error', text: "Verification failed. Try again." });
    } finally {
      setIsValidatingCoupon(false);
    }
  };

  const removeCoupon = () => {
    setAppliedCoupon(null);
    setCouponCode('');
    setCouponMessage(null);
  };

  const handleStartChat = () => {
    if (!currentUser) return;
    navigate('/dashboard', {
        state: {
            tab: 'messages',
            chatWith: state.account.listedBy,
            accountId: state.account.id
        }
    });
  };

  const handleSubmitPayment = async () => {
    if (!utr) {
      setError('Please enter the Transaction ID / UTR number.');
      return;
    }

    // Relaxed validation: Allow alphanumeric and check for reasonable length (e.g., 6+ chars)
    if (utr.length < 6) {
      setError('Invalid UTR. Please enter a valid reference ID.');
      return;
    }

    // Increment Coupon usage if applied
    if (appliedCoupon) {
       await StorageService.incrementCouponUsage(appliedCoupon.code);
    }

    if (state.orderId) {
       // Update existing PENDING booking
       const booking: Booking = {
         orderId,
         accountId: state.account.id,
         accountName: state.account.name,
         durationLabel: state.durationLabel,
         hours: state.hours,
         totalPrice: finalPrice, // Use discounted price
         startTime: startDateTime.toISOString(),
         endTime: endDateTime.toISOString(),
         status: BookingStatus.PENDING, 
         createdAt: new Date().toISOString(),
         utr: utr,
         customerId: currentUser?.id,
         customerName: currentUser?.name,
         couponCode: appliedCoupon ? appliedCoupon.code : undefined,
         discountApplied: appliedCoupon ? discountAmount : undefined
       };
       await StorageService.updateBooking(booking);
    } else {
       // Legacy Fallback: Create new booking
       const newBooking: Booking = {
        orderId,
        accountId: state.account.id,
        accountName: state.account.name,
        durationLabel: state.durationLabel,
        hours: state.hours,
        totalPrice: finalPrice, // Use discounted price
        startTime: startDateTime.toISOString(),
        endTime: endDateTime.toISOString(),
        status: BookingStatus.PENDING,
        createdAt: new Date().toISOString(),
        utr: utr,
        customerId: currentUser?.id, // Link to logged in user
        customerName: currentUser?.name,
        couponCode: appliedCoupon ? appliedCoupon.code : undefined,
        discountApplied: appliedCoupon ? discountAmount : undefined
      };
      await StorageService.createBooking(newBooking);
    }

    // 2. Construct WhatsApp Message
    const timeString = state.startMode === 'later' 
      ? startDateTime.toLocaleString('en-IN', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
      : "Immediate";

    let message = `
*PAYMENT SUBMITTED*
---------------------
*Order ID:* ${orderId}
*Valorant ID:* ${state.account.name}
*Duration:* ${state.durationLabel}
*Price:* ₹${finalPrice}`;

    if (appliedCoupon) {
      message += `\n*Coupon:* ${appliedCoupon.code} (-₹${discountAmount})`;
    }

    message += `\n*Start Time:* ${timeString}
*UTR/Ref ID:* ${utr}
---------------------
I have made the payment. Please verify.
    `.trim();

    // 3. Redirect to WhatsApp (Open in new tab to avoid iframe/preview blocks)
    const whatsappUrl = `https://wa.me/919860185116?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');

    // 4. Redirect user to Dashboard to track status
    navigate('/dashboard');
  };

  const isUserListed = !!state.account.listedBy && state.account.listedBy !== currentUser?.id;

  return (
    <div className="max-w-3xl mx-auto px-4 py-8">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 mb-6 text-slate-400 text-sm">
        <span onClick={() => navigate('/browse')} className="cursor-pointer hover:text-white">Browse</span>
        <ArrowRight className="w-3 h-3" />
        <span className="text-white">Checkout</span>
      </div>

      <div className="space-y-6">

         {/* SECTION 1: TIMER */}
         <div className="bg-brand-surface border border-brand-accent/30 rounded-xl p-4 flex items-center justify-between shadow-[0_0_15px_rgba(255,70,85,0.1)]">
             <div className="flex items-center gap-2 text-brand-accent">
               <Timer className="w-5 h-5" />
               <span className="font-bold">Session Time</span>
             </div>
             <div className="font-mono text-xl font-bold">{formatTimer(timer)}</div>
         </div>

         {/* SECTION 2: ORDER SUMMARY (Top) */}
         <div className="bg-brand-surface border border-white/10 rounded-xl p-6 relative overflow-hidden">
            <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
               <span className="w-8 h-8 rounded-full bg-brand-surface border border-white/20 flex items-center justify-center text-sm text-slate-400">1</span>
               Order Summary
            </h2>

            <div className="flex flex-col md:flex-row gap-6 pb-6 border-b border-white/10">
               <div className="flex items-start gap-4 flex-1">
                  <img src={state.account.imageUrl} className="w-24 h-24 rounded-lg object-cover border border-white/10" alt="" />
                  <div>
                    <h3 className="font-bold text-xl text-white">{state.account.name}</h3>
                    <div className="mt-1 inline-block text-xs font-bold text-brand-secondary bg-brand-secondary/10 px-2 py-0.5 rounded border border-brand-secondary/20 uppercase tracking-wider">
                      {state.account.rank}
                    </div>
                    <div className="text-sm text-slate-400 mt-2 font-mono">Order: {orderId}</div>

                    {/* Chat with Owner Button */}
                    {isUserListed && currentUser && (
                        <button 
                            onClick={handleStartChat}
                            className="mt-3 inline-flex items-center gap-1.5 px-3 py-1.5 bg-brand-dark hover:bg-brand-cyan/10 text-slate-300 hover:text-brand-cyan border border-white/10 hover:border-brand-cyan/50 rounded-lg text-xs font-bold uppercase tracking-wider transition-all"
                        >
                            <MessageCircle size={14} />
                            Chat with Owner
                        </button>
                    )}
                  </div>
               </div>

               {/* Totals Display */}
               <div className="flex-1 space-y-2 md:text-right">
                  <div className="flex justify-between md:justify-end gap-8 text-slate-300">
                    <span>Duration</span>
                    <span className="text-white font-bold">{state.durationLabel}</span>
                  </div>
                  <div className="flex justify-between md:justify-end gap-8 text-slate-300">
                    <span>Subtotal</span>
                    <span className={state.originalPrice ? 'line-through text-slate-500' : 'text-white'}>
                       ₹{state.originalPrice || state.price}
                    </span>
                  </div>
                  {state.originalPrice && (
                     <div className="flex justify-between md:justify-end gap-8 text-brand-accent font-bold text-sm">
                        <span>24h Discount</span>
                        <span>-₹{(state.originalPrice - state.price).toFixed(0)}</span>
                     </div>
                  )}
                  {appliedCoupon && (
                     <div className="flex justify-between md:justify-end gap-8 text-green-400 font-bold text-sm">
                        <span>Coupon ({appliedCoupon.code})</span>
                        <span>-₹{discountAmount}</span>
                     </div>
                  )}
                  <div className="flex justify-between md:justify-end gap-8 items-center pt-2 border-t border-white/10 mt-2">
                    <span className="font-bold text-lg">Total Pay</span>
                    <span className="font-bold text-2xl text-brand-accent">₹{finalPrice}</span>
                  </div>
               </div>
            </div>

            {/* Schedule & Coupon Block */}
            <div className="grid md:grid-cols-2 gap-6 mt-6">
                {/* Schedule */}
                <div className="bg-white/5 rounded-lg p-4 border border-white/5">
                    <div className="flex items-center gap-2 mb-3 text-brand-accent font-bold text-sm uppercase tracking-wide">
                        <CalendarClock className="w-4 h-4" /> Schedule
                    </div>
                    <div className="space-y-2 text-sm">
                        <div className="flex justify-between">
                            <span className="text-slate-400">Start Time</span>
                            <span className="text-white font-mono">
                                {state.startMode === 'now' 
                                ? 'Immediate' 
                                : startDateTime.toLocaleString('en-IN', {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'})}
                            </span>
                        </div>
                        <div className="flex justify-between">
                            <span className="text-slate-400">End Time</span>
                            <span className="text-white font-mono">
                                {endDateTime.toLocaleString('en-IN', {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'})}
                            </span>
                        </div>
                    </div>
                </div>

                {/* Coupon */}
                <div>
                     <div className="relative h-full">
                        {appliedCoupon ? (
                          <div className="bg-green-500/10 border border-green-500/30 rounded-lg p-3 flex justify-between items-center h-full">
                             <div className="flex items-center gap-2">
                                <Ticket className="w-5 h-5 text-green-400" />
                                <div>
                                   <div className="text-sm text-green-400 font-bold uppercase tracking-wider">{appliedCoupon.code}</div>
                                   <div className="text-[10px] text-green-300">Discount Applied</div>
                                </div>
                             </div>
                             <button onClick={removeCoupon} className="text-slate-500 hover:text-white p-2"><XCircle className="w-5 h-5" /></button>
                          </div>
                        ) : (
                          <div className="flex gap-2 h-full items-start">
                             <div className="relative flex-1">
                                <Ticket className="absolute left-3 top-3 w-4 h-4 text-slate-500" />
                                <input 
                                  type="text" 
                                  placeholder="COUPON CODE"
                                  value={couponCode}
                                  onChange={(e) => {
                                     setCouponCode(e.target.value.toUpperCase());
                                     setCouponMessage(null);
                                  }}
                                  onKeyPress={(e) => e.key === 'Enter' && handleApplyCoupon()}
                                  className="w-full bg-brand-dark border border-white/10 rounded-lg py-3 pl-10 pr-3 text-sm text-white focus:border-brand-accent outline-none font-mono uppercase"
                                />
                             </div>
                             <button 
                               onClick={handleApplyCoupon}
                               disabled={isValidatingCoupon || !couponCode}
                               className="px-5 py-3 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-xs font-bold uppercase tracking-wide transition-colors disabled:opacity-50 h-[46px]"
                             >
                               {isValidatingCoupon ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Apply'}
                             </button>
                          </div>
                        )}
                        {couponMessage && (
                           <div className={`text-[10px] mt-2 flex items-center gap-1.5 ${couponMessage.type === 'success' ? 'text-green-400' : 'text-red-400'}`}>
                              {couponMessage.type === 'success' ? <CheckCircle size={12} /> : <XCircle size={12} />}
                              {couponMessage.text}
                           </div>
                        )}
                     </div>
                </div>
            </div>
         </div>

         {/* SECTION 3: PAYMENT & VERIFICATION (Combined for better flow) */}
         <div className="bg-brand-surface border border-white/10 rounded-xl p-6 relative overflow-hidden">
             {/* Background Glow */}
             <div className="absolute top-0 right-0 w-64 h-64 bg-brand-accent/5 blur-3xl rounded-full pointer-events-none"></div>

             <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
               <span className="w-8 h-8 rounded-full bg-brand-accent flex items-center justify-center text-sm text-white shadow-[0_0_15px_rgba(255,70,85,0.4)]">2</span>
               Make Payment
             </h2>

             <div className="grid md:grid-cols-2 gap-8">
                 {/* QR Code Column */}
                 <div className="flex flex-col items-center">
                    {/* Mobile Pay Button */}
                    <div className="md:hidden w-full mb-6">
                      <a 
                        href={upiString}
                        className="w-full bg-white text-brand-darker font-bold py-4 rounded-xl shadow-lg flex items-center justify-center gap-2 hover:bg-slate-100 transition-colors animate-pulse no-underline"
                      >
                        <Smartphone className="w-6 h-6" />
                        Tap to Pay via UPI
                      </a>
                      <div className="flex items-center gap-2 justify-center mt-2 text-slate-500 text-xs">
                          <span className="w-12 h-px bg-white/10"></span> OR <span className="w-12 h-px bg-white/10"></span>
                      </div>
                    </div>

                    <div className="bg-white p-4 rounded-xl shadow-inner relative group mx-auto">
                      <img 
                        src={qrCodeUrl} 
                        alt="UPI QR Code" 
                        className="w-48 h-48 mix-blend-multiply"
                      />
                      {/* Scan Overlay */}
                      <div className="absolute top-0 left-0 w-full h-1 bg-brand-accent/50 animate-[scan_2s_infinite_linear] pointer-events-none" />
                    </div>
                    <div className="text-center mt-4">
                        <p className="text-slate-400 text-sm mb-1">Scan to pay</p>
                        <p className="text-2xl font-black text-white">₹{finalPrice}</p>
                    </div>
                 </div>

                 {/* UTR Column */}
                 <div className="flex flex-col justify-center space-y-6">
                    <div className="bg-brand-dark p-4 rounded-lg border border-white/10">
                       <div className="text-xs text-slate-400 uppercase font-bold mb-2">Merchant UPI ID</div>
                       <div className="flex items-center justify-between">
                          <span className="font-mono text-white text-lg">{UPI_ID}</span>
                          <button 
                             onClick={() => {
                               navigator.clipboard.writeText(UPI_ID);
                             }}
                             className="text-brand-accent hover:text-white transition-colors"
                          >
                            <Copy className="w-5 h-5" />
                          </button>
                       </div>
                    </div>

                    <div className="border-t border-white/10 pt-6">
                        <label className="block text-sm font-bold text-white mb-2">
                           Enter Payment Reference ID (UTR)
                        </label>
                        <input 
                          type="text" 
                          value={utr}
                          onChange={(e) => {
                            setUtr(e.target.value);
                            setError('');
                          }}
                          placeholder="12-digit UTR (e.g. 3245xxxxxxxx)"
                          className="w-full bg-brand-dark border border-white/10 rounded-lg px-4 py-4 text-white focus:border-brand-accent focus:outline-none mb-2 font-mono text-lg tracking-widest placeholder:tracking-normal"
                          maxLength={12}
                        />
                        {error && <p className="text-red-500 text-xs mb-3 font-bold flex items-center gap-1"><AlertCircle size={12}/> {error}</p>}

                        <button 
                          onClick={handleSubmitPayment}
                          className="w-full bg-brand-accent hover:bg-red-600 text-white font-bold py-4 rounded-lg flex items-center justify-center gap-2 transition-all shadow-lg shadow-brand-accent/20 mt-2"
                        >
                          <Send className="w-5 h-5" />
                          VERIFY & BOOK SLOT
                        </button>
                        <p className="text-[10px] text-center mt-3 text-slate-500">
                           Instant verification via WhatsApp protocol.
                        </p>
                    </div>
                 </div>
             </div>
         </div>
      </div>
    </div>
  );
};

export default Checkout;

import React, { useState, useEffect, useRef } from 'react';
import { Navigate, useNavigate, useLocation } from 'react-router-dom';
import { createPortal } from 'react-dom';
import { StorageService } from '../services/storage';
import { User, Booking, BookingStatus, Account, Message } from '../types';
import { 
  User as UserIcon, Clock, History, LifeBuoy, LogOut, 
  Gamepad2, Copy, Eye, EyeOff, ShieldCheck, 
  AlertTriangle, ChevronRight, MessageCircle, Award, Sparkles, Lock, ListPlus, Edit2, Trash2,
  Inbox, CheckCircle2, XCircle, Key, Send, Hash, ArrowLeft
} from 'lucide-react';

const UserDashboard: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'rentals' | 'listings' | 'requests' | 'messages' | 'history' | 'profile' | 'support' | 'rewards'>('overview');
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [myListings, setMyListings] = useState<Account[]>([]);
  const [incomingRequests, setIncomingRequests] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);

  // Chat State
  const [conversations, setConversations] = useState<{userId: string, userName: string, accountId: string, accountName: string, lastMessage: Message, unreadCount: number}[]>([]);
  const [activeChat, setActiveChat] = useState<{userId: string, userName: string, accountId: string, accountName: string} | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const chatBottomRef = useRef<HTMLDivElement>(null);

  // Password Edit Modal
  const [editingPasswordId, setEditingPasswordId] = useState<string | null>(null);
  const [newPassword, setNewPassword] = useState('');

  // Load user data
  useEffect(() => {
    const loadData = async () => {
      const currentUser = StorageService.getCurrentUser();
      if (currentUser) {
        setUser(currentUser);

        // Fetch My Rentals
        const userBookings = await StorageService.getUserBookings(currentUser.id);
        userBookings.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
        setBookings(userBookings);

        // Fetch My Listings
        const listings = await StorageService.getUserListings(currentUser.id);
        setMyListings(listings);

        // Fetch Incoming Booking Requests for my listings
        const allBookings = await StorageService.getBookings();
        const myAccountIds = new Set(listings.map(l => l.id));
        const requests = allBookings.filter(b => myAccountIds.has(b.accountId));
        requests.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
        setIncomingRequests(requests);

        // Load Conversations
        await loadConversations(currentUser.id);
      }
      setLoading(false);
    };
    loadData();

    // Check for direct chat link in location state
    if (location.state && location.state.tab === 'messages') {
        setActiveTab('messages');
        const { chatWith, accountId } = location.state;
        if (chatWith && accountId) {
            // Find account name
            StorageService.getAccountById(accountId).then(acc => {
                const name = acc?.name || 'Unknown Account';
                // Try to find existing user name if possible, else generic
                // In real app, we'd fetch user profile. Here using placeholder.
                const userName = 'User ' + chatWith.substring(0, 4); 
                openChat({ userId: chatWith, userName, accountId, accountName: name });
            });
        }
    }

    const unsubscribe = StorageService.subscribe(loadData);
    return () => { unsubscribe(); };
  }, [location.state]);

  const loadConversations = async (userId: string) => {
      const allMsgs = await StorageService.getAllUserMessages(userId);
      const convMap = new Map<string, {userId: string, userName: string, accountId: string, accountName: string, lastMessage: Message, unreadCount: number}>();

      for (const msg of allMsgs) {
          const otherId = msg.senderId === userId ? msg.receiverId : msg.senderId;
          const key = `${otherId}-${msg.accountId}`;

          if (!convMap.has(key)) {
              convMap.set(key, {
                  userId: otherId,
                  userName: 'User ' + otherId.substring(0, 4), // Placeholder name
                  accountId: msg.accountId,
                  accountName: msg.accountName || 'Valorant ID',
                  lastMessage: msg,
                  unreadCount: 0
              });
          }

          const conv = convMap.get(key)!;
          if (msg.receiverId === userId && !msg.isRead) {
              conv.unreadCount++;
          }
      }
      setConversations(Array.from(convMap.values()));
  };

  // Poll messages when chat is active
  useEffect(() => {
      if (!activeChat || !user) return;

      const pollMessages = async () => {
          const msgs = await StorageService.getMessages(user.id, activeChat.userId, activeChat.accountId);
          setMessages(msgs);

          // Mark as read
          if (msgs.some(m => m.receiverId === user.id && !m.isRead)) {
              await StorageService.markMessagesAsRead(activeChat.userId, user.id, activeChat.accountId);
              loadConversations(user.id); // Refresh counts
          }
      };

      pollMessages();
      const interval = setInterval(pollMessages, 3000);
      return () => clearInterval(interval);
  }, [activeChat, user]);

  useEffect(() => {
      chatBottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleLogout = () => {
    StorageService.logoutUser();
    navigate('/');
  };

  const handleDeleteListing = async (id: string) => {
    if(window.confirm("Are you sure you want to delete this listing?")) {
      await StorageService.deleteAccount(id);
    }
  };

  const handleAuthorize = async (booking: Booking) => {
     if(window.confirm("Authorize this booking? Credentials will be revealed to the renter.")) {
        // If start time is future, use PRE_BOOKED, else ACTIVE
        const isFuture = new Date(booking.startTime).getTime() > Date.now();
        const status = isFuture ? BookingStatus.PRE_BOOKED : BookingStatus.ACTIVE;
        try {
           await StorageService.updateBookingStatus(booking.orderId, status);
        } catch (e: any) {
           alert(e.message);
        }
     }
  };

  const handleCancelBooking = async (orderId: string) => {
     if(window.confirm("Reject this booking request?")) {
        await StorageService.updateBookingStatus(orderId, BookingStatus.CANCELLED);
     }
  };

  const handleSavePassword = async () => {
     if (editingPasswordId && newPassword) {
        await StorageService.updateAccountPassword(editingPasswordId, newPassword);
        setEditingPasswordId(null);
        setNewPassword('');
        alert("Password updated successfully.");
     }
  };

  const openChat = (chat: {userId: string, userName: string, accountId: string, accountName: string}) => {
      setActiveChat(chat);
      // Mobile view handling: CSS classes will hide list
  };

  const handleSendMessage = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newMessage.trim() || !activeChat || !user) return;

      const msg: Message = {
          id: 'MSG-' + Date.now(),
          senderId: user.id,
          receiverId: activeChat.userId,
          accountId: activeChat.accountId,
          accountName: activeChat.accountName,
          content: newMessage.trim(),
          createdAt: new Date().toISOString(),
          isRead: false
      };

      await StorageService.sendMessage(msg);
      setMessages([...messages, msg]);
      setNewMessage('');
      loadConversations(user.id);
  };

  if (loading) return null;
  if (!user) return <Navigate to="/login" />;

  const activeBookings = bookings.filter(b => b.status === BookingStatus.ACTIVE || b.status === BookingStatus.PENDING || b.status === BookingStatus.PRE_BOOKED);
  const pastBookings = bookings.filter(b => b.status === BookingStatus.COMPLETED || b.status === BookingStatus.CANCELLED);

  const renderTabContent = () => {
